                            <h4 className="text-lg font-medium text-gray-900 dark:text-white mb-2">
                              {patientsSearchTerm ? 'No se encontraron pacientes' : 'No tienes pacientes asignados'}
                            </h4>
                            <p className="text-gray-600 dark:text-gray-400">
                              {patientsSearchTerm 
                                ? `No hay pacientes que coincidan con "${patientsSearchTerm}"`
                                : 'No se encontraron pacientes para tu cuenta.'
                              }
                            </p>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              </div>
              <div className="bg-gray-50 dark:bg-gray-700 px-4 py-3 sm:px-6 sm:flex sm:flex-row-reverse">
                <button
                  type="button"
                  onClick={closePatientsModal}
                  className="mt-3 w-full inline-flex justify-center rounded-md border border-gray-300 dark:border-gray-600 shadow-sm px-4 py-2 bg-white dark:bg-gray-600 text-base font-medium text-gray-700 dark:text-gray-200 hover:bg-gray-50 dark:hover:bg-gray-500 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 sm:mt-0 sm:ml-3 sm:w-auto sm:text-sm"
                >
                  Cerrar
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { Doctor, getSpecialtyOptions, DEFAULT_DOCTORS } from '../../../config/doctors';
import { DoctorService } from '../../../services/doctorService';
import { useRoleBasedAccess } from '../../../hooks/useRoleBasedAccess';
import { useClerkUsers, ClerkUser } from '../../../hooks/useClerkUsers';
import { UserAvatar } from '@/components/UserAvatar';
import { usePagePreferences } from '@/hooks/useUserPreferences';
import AccessDenied from '@/components/AccessDenied';

export default function DoctorsPage() {
  const [doctors, setDoctors] = useState<Doctor[]>([]);
  const [loading, setLoading] = useState(true);
  const [isEditing, setIsEditing] = useState(false);
  const [editingDoctor, setEditingDoctor] = useState<Doctor | null>(null);
  const [formData, setFormData] = useState({
    id: '',
    name: '',
    specialty: '',
    userId: '',
    userEmail: ''
  });
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedSpecialty, setSelectedSpecialty] = useState('');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const { users: clerkUsers, loading: usersLoading } = useClerkUsers();

  // Use page preferences for doctores page
  const { preferences: pagePrefs, updatePreferences: updatePagePrefs, loading: prefsLoading } = usePagePreferences('doctores');

  // Initialize state from preferences or defaults
  const [recordsPerPagePref, setRecordsPerPagePref] = useState(pagePrefs?.recordsPerPage || 25);
  const [sortBy, setSortBy] = useState<'name' | 'specialty'>(pagePrefs?.sortBy || 'name');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>(pagePrefs?.sortOrder || 'asc');
  const [currentPage, setCurrentPage] = useState(1);

  // Load doctors from service on component mount and when window gains focus
  useEffect(() => {
    const loadDoctors = async () => {
      try {
        const doctorsData = await DoctorService.getDoctors();
        setDoctors(doctorsData);
      } catch (error) {
        console.error('Error loading doctors:', error);
      } finally {
        setLoading(false);
      }
    };

    loadDoctors();

    // Refresh doctors when window gains focus (in case user modifies in another tab)
    const handleFocus = () => {
      loadDoctors();
    };

    window.addEventListener('focus', handleFocus);

    return () => {
      window.removeEventListener('focus', handleFocus);
    };
  }, []);

  // Sync preferences when they load
  useEffect(() => {
    if (pagePrefs && !prefsLoading) {
      if (pagePrefs.viewMode) setViewMode(pagePrefs.viewMode);
      if (pagePrefs.recordsPerPage) setRecordsPerPagePref(pagePrefs.recordsPerPage);
      if (pagePrefs.sortBy) setSortBy(pagePrefs.sortBy);
      if (pagePrefs.sortOrder) setSortOrder(pagePrefs.sortOrder);
    }
  }, [pagePrefs, prefsLoading]);

  // Save viewMode preference with debounce
  useEffect(() => {
    if (!prefsLoading && viewMode !== (pagePrefs?.viewMode || 'grid')) {
      const timeoutId = setTimeout(() => {
        updatePagePrefs({ viewMode });
      }, 500);
      return () => clearTimeout(timeoutId);
    }
  }, [viewMode, prefsLoading, pagePrefs?.viewMode, updatePagePrefs]);

  // Save recordsPerPage preference with debounce
  useEffect(() => {
    if (!prefsLoading && recordsPerPagePref !== (pagePrefs?.recordsPerPage || 25)) {
      const timeoutId = setTimeout(() => {
        updatePagePrefs({ recordsPerPage: recordsPerPagePref });
      }, 500);
      return () => clearTimeout(timeoutId);
    }
  }, [recordsPerPagePref, prefsLoading, pagePrefs?.recordsPerPage, updatePagePrefs]);

  // Save sortBy preference with debounce
  useEffect(() => {
    if (!prefsLoading && sortBy !== (pagePrefs?.sortBy || 'name')) {
      const timeoutId = setTimeout(() => {
        updatePagePrefs({ sortBy });
      }, 500);
      return () => clearTimeout(timeoutId);
    }
  }, [sortBy, prefsLoading, pagePrefs?.sortBy, updatePagePrefs]);

  // Save sortOrder preference with debounce
  useEffect(() => {
    if (!prefsLoading && sortOrder !== (pagePrefs?.sortOrder || 'asc')) {
      const timeoutId = setTimeout(() => {
        updatePagePrefs({ sortOrder });
      }, 500);
      return () => clearTimeout(timeoutId);
    }
  }, [sortOrder, prefsLoading, pagePrefs?.sortOrder, updatePagePrefs]);

  // Check if user has proper access (only tech_support and admin)
  const { userRole, permissions } = useRoleBasedAccess();

  // Check if user can manage doctors
  const canManageDoctores = permissions?.canManageDoctores || false;

  // Access control: only tech_support and admin can access
  if (!userRole || (userRole !== 'tech_support' && userRole !== 'admin')) {
    return (
      <AccessDenied
        title="Acceso Denegado"
        message="No tienes permisos para acceder a la gestión de doctores."
        explanation="Esta área es exclusiva para administradores y personal de soporte técnico que pueden gestionar doctores."
        contactInfo="Si necesitas acceso, contacta a un administrador del sistema."
        onGoBack={() => window.history.back()}
      />
    );
  }

  // Filter doctors based on search and specialty
  const filteredDoctors = doctors.filter(doctor => {
    const matchesSearch = doctor.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         doctor.specialty.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesSpecialty = !selectedSpecialty || doctor.specialty === selectedSpecialty;
    return matchesSearch && matchesSpecialty;
  }).sort((a, b) => {
    let comparison = 0;

    switch (sortBy) {
      case 'name':
        comparison = a.name.localeCompare(b.name);
        break;
      case 'specialty':
        comparison = a.specialty.localeCompare(b.specialty);
        break;
    }

    return sortOrder === 'asc' ? comparison : -comparison;
  });

  // Pagination calculations
  const totalDoctors = filteredDoctors.length;
  const totalPages = Math.ceil(totalDoctors / recordsPerPagePref);
  const startIndex = (currentPage - 1) * recordsPerPagePref;
  const endIndex = startIndex + recordsPerPagePref;
  const currentDoctors = filteredDoctors.slice(startIndex, endIndex);

  // Reset to page 1 when search term or records per page changes
  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, recordsPerPagePref, selectedSpecialty, sortBy, sortOrder]);

  const getPaginationNumbers = () => {
    const pages = [];
    const maxVisiblePages = 5;

    if (totalPages <= maxVisiblePages) {
      for (let i = 1; i <= totalPages; i++) {
        pages.push(i);
      }
    } else {
      if (currentPage <= 3) {
        for (let i = 1; i <= 4; i++) {
          pages.push(i);
        }
        pages.push('...');
        pages.push(totalPages);
      } else if (currentPage >= totalPages - 2) {
        pages.push(1);
        pages.push('...');
        for (let i = totalPages - 3; i <= totalPages; i++) {
          pages.push(i);
        }
      } else {
        pages.push(1);
        pages.push('...');
        for (let i = currentPage - 1; i <= currentPage + 1; i++) {
          pages.push(i);
        }
        pages.push('...');
        pages.push(totalPages);
      }
    }

    return pages;
  };

  const handlePageChange = (page: number) => {
    setCurrentPage(page);
  };

  const handleRecordsPerPageChange = (value: number) => {
    setRecordsPerPagePref(value);
  };

  // Get unique specialties from current doctors
  const uniqueSpecialties = [...new Set(doctors.map(doctor => doctor.specialty))];

  const handleAddDoctor = () => {
    setIsEditing(true);
    setEditingDoctor(null);
    setFormData({ id: '', name: '', specialty: '', userId: '', userEmail: '' });
  };

  const handleEditDoctor = (doctor: Doctor) => {
    setIsEditing(true);
    setEditingDoctor(doctor);
    setFormData({
      id: doctor.id,
      name: doctor.name,
      specialty: doctor.specialty,
      userId: doctor.user_id || '',
      userEmail: doctor.user_email || ''
    });
  };

  const handleDeleteDoctor = async (doctorId: string) => {
    if (window.confirm('¿Está seguro de que desea eliminar este doctor?')) {
      try {
        await DoctorService.deleteDoctor(doctorId);
        // Force refresh by reloading from database
        const updatedDoctors = await DoctorService.getDoctors();
        setDoctors(updatedDoctors);
      } catch (error) {
        console.error('Error deleting doctor:', error);
        alert('Error al eliminar el doctor');
      }
    }
  };

  const handleSaveDoctor = async () => {
    try {
      if (editingDoctor) {
        // Update existing doctor
        const updatedDoctor = await DoctorService.updateDoctor(editingDoctor.id, {
          name: formData.name,
          specialty: formData.specialty,
          user_id: formData.userId || undefined,
          user_email: formData.userEmail || undefined
        });

        setDoctors(doctors.map(d => d.id === editingDoctor.id ? updatedDoctor : d));
        alert('Doctor actualizado exitosamente');
      } else {
        // Add new doctor
        const newDoctor = await DoctorService.createDoctor({
          name: formData.name,
          specialty: formData.specialty,
          user_id: formData.userId || undefined,
          user_email: formData.userEmail || undefined
        });

        setDoctors([...doctors, newDoctor]);
        alert('Doctor agregado exitosamente');
      }
      setEditingDoctor(null);
      setFormData({ id: '', name: '', specialty: '', userId: '', userEmail: '' });
    } catch (error) {
      console.error('Error saving doctor:', error);
      alert('Error al guardar el doctor');
    }
  };

  const handleResetToDefaults = async () => {
    if (window.confirm('¿Está seguro de que desea restablecer los doctores a los valores por defecto? Esto eliminará todos los doctores personalizados.')) {
      try {
        // Add default doctors to Supabase
        for (const defaultDoctor of DEFAULT_DOCTORS) {
          await DoctorService.createDoctor({
            name: defaultDoctor.name,
            specialty: defaultDoctor.specialty
          });
        }
        setDoctors(DEFAULT_DOCTORS);
        alert('Doctores restablecidos a los valores por defecto');
      } catch (error) {
        console.error('Error resetting doctors:', error);
        alert('Error al restablecer los doctores');
      }
    }
  };

  const handleCancel = () => {
    setIsEditing(false);
    setEditingDoctor(null);
    setFormData({ id: '', name: '', specialty: '', userId: '', userEmail: '' });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-lg">Cargando...</div>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-6xl mx-auto">
      <div className="flex justify-between items-center mb-6">
        <div className="flex items-center space-x-4">
          {/* Title moved to main header */}
        </div>

        <button
          onClick={handleAddDoctor}
          className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-colors"
        >
          <i className="fas fa-plus mr-2"></i>
          Agregar Doctor
        </button>
      </div>

      {/* Search Bar */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6">
        <div className="flex-1">
          <div className="flex flex-col sm:flex-row gap-4">
            <div className="relative flex-1">
              <input
                type="text"
                placeholder="Buscar por nombre o especialidad..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full px-4 py-2 pr-10 border border-gray-300 dark:border-gray-600 rounded-lg focus:outline-none focus:ring-2 focus:ring-teal-500 dark:bg-gray-700 dark:text-white"
              />
              <i className="fas fa-search absolute right-3 top-3 text-gray-400"></i>
            </div>

            {/* Sort Controls */}
            <div className="flex items-center gap-2">
              <label className="text-sm font-medium text-gray-700 dark:text-gray-300">Ordenar por:</label>
              <select
                value={sortBy}
                onChange={(e) => setSortBy(e.target.value as 'name' | 'specialty')}
                className="px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:outline-none focus:ring-2 focus:ring-teal-500 dark:bg-gray-700 dark:text-white"
              >
                <option value="name">Nombre</option>
                <option value="specialty">Especialidad</option>
              </select>
              <button
                onClick={() => setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc')}
                className="px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700 focus:outline-none focus:ring-2 focus:ring-teal-500 dark:bg-gray-700 dark:text-white"
                title={`Orden ${sortOrder === 'asc' ? 'ascendente' : 'descendente'}`}
              >
                <i className={`fas fa-sort-amount-${sortOrder === 'asc' ? 'up' : 'down'}`}></i>
              </button>
            </div>

            {/* Filter Controls */}
            <div className="flex items-center gap-2">
              <select
                value={selectedSpecialty}
                onChange={(e) => setSelectedSpecialty(e.target.value)}
                className="px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:outline-none focus:ring-2 focus:ring-teal-500 dark:bg-gray-700 dark:text-white"
              >
                <option value="">Todas las especialidades</option>
                {uniqueSpecialties.map(specialty => (
                  <option key={specialty} value={specialty}>
                    {specialty}
                  </option>
                ))}
              </select>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          {/* View Toggle Button */}
          <div className="flex items-center space-x-2 bg-gray-100 dark:bg-gray-700 rounded-lg p-1">
            <button
              onClick={() => setViewMode('list')}
              className={`px-3 py-1.5 rounded-md text-sm font-medium transition-colors duration-200 ${
                viewMode === 'list'
                  ? 'bg-white text-gray-900 shadow-sm'
                  : 'text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white'
              }`}
            >
              <i className="fas fa-list mr-2"></i>
              Lista
            </button>
            <button
              onClick={() => setViewMode('grid')}
              className={`px-3 py-1.5 rounded-md text-sm font-medium transition-colors duration-200 ${
                viewMode === 'grid'
                  ? 'bg-white text-gray-900 shadow-sm'
                  : 'text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white'
              }`}
            >
              <i className="fas fa-th-large mr-2"></i>
              Cuadrícula
            </button>
          </div>
        </div>
      </div>

      {/* Edit/Add Modal */}
      {isEditing && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white dark:bg-gray-800 rounded-lg p-6 w-full max-w-md">
            <h2 className="text-xl font-bold mb-4 text-gray-900 dark:text-white">
              {editingDoctor ? 'Editar Doctor' : 'Agregar Nuevo Doctor'}
            </h2>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Nombre del Doctor:
                </label>
                <input
                  type="text"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  placeholder="Ej: Dra. María González"
                  className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Especialidad:
                </label>
                <select
                  value={formData.specialty}
                  onChange={(e) => setFormData({ ...formData, specialty: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
                >
                  <option value="">Seleccionar especialidad</option>
                  {getSpecialtyOptions().slice(1).map(option => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Usuario Asignado (opcional):
                </label>
                <select
                  value={formData.userId}
                  onChange={(e) => {
                    const selectedUser = clerkUsers.find(u => u.id === e.target.value);
                    setFormData({ 
                      ...formData, 
                      userId: e.target.value,
                      userEmail: selectedUser?.emailAddress || ''
                    });
                  }}
                  className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 dark:bg-gray-700 dark:text-white"
                  disabled={usersLoading}
                >
                  <option value="">
                    {usersLoading ? 'Cargando usuarios...' : 'Seleccionar usuario'}
                  </option>
                  {clerkUsers.map(user => (
                    <option key={user.id} value={user.id}>
                      {user.firstName} {user.lastName} - {user.emailAddress}
                    </option>
                  ))}
                </select>
                <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                  {usersLoading 
                    ? 'Cargando usuarios de Clerk...'
                    : clerkUsers.length === 0 
                      ? 'No se encontraron usuarios con rol de doctor'
                      : 'Seleccione un usuario de Clerk para asignar a este doctor'
                  }
                </p>
              </div>
            </div>
            <div className="flex justify-end space-x-3 mt-6">
              <button
                onClick={handleCancel}
                className="px-4 py-2 text-gray-600 dark:text-gray-400 border border-gray-300 dark:border-gray-600 rounded-md hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors"
              >
                Cancelar
              </button>
              <button
                onClick={handleSaveDoctor}
                className="px-4 py-2 bg-blue-600 dark:bg-blue-700 text-white rounded-md hover:bg-blue-700 dark:hover:bg-blue-800 transition-colors"
              >
                {editingDoctor ? 'Actualizar' : 'Agregar'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Doctors Display */}
      {viewMode === 'grid' ? (
        /* Grid View */
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {currentDoctors.map((doctor) => {
            const assignedUser = clerkUsers.find(u => u.id === doctor.user_id);
            return (
              <div key={doctor.id} className="bg-white dark:bg-gray-800 rounded-2xl shadow-xl hover:shadow-2xl transform hover:-translate-y-1 transition-all duration-300 border border-gray-200 dark:border-gray-700 overflow-hidden group">
                {/* Doctor Header */}
                <div className="bg-gradient-to-r from-blue-500 to-blue-600 p-4 text-white">
                  <div className="flex justify-between items-start">
                    <div>
                      <h3 className="text-lg font-bold">{doctor.name}</h3>
                      <p className="text-blue-100 text-sm">{doctor.specialty}</p>
                    </div>
                    <span className="px-2 py-1 bg-white/20 rounded-full text-xs font-medium">
                      {doctor.id}
                    </span>
                  </div>
                </div>

                {/* Doctor Content */}
                <div className="p-4">
                  {/* User Assignment */}
                  <div className="mb-4">
                    <div className="flex items-center justify-between">
                      <span className="text-sm font-medium text-gray-700 dark:text-gray-300">Usuario Asignado</span>
                      {doctor.user_id ? (
                        <UserAvatar
                          userId={assignedUser?.id}
                          firstName={assignedUser?.firstName}
                          lastName={assignedUser?.lastName}
                          emailAddress={assignedUser?.emailAddress}
                          profileImageUrl={assignedUser?.profileImageUrl}
                          size="sm"
                          showName={true}
                          showEmail={true}
                        />
                      ) : (
                        <UserAvatar
                          size="sm"
                          showName={true}
                          showEmail={false}
                        />
                      )}
                    </div>
                  </div>

                  {/* Actions */}
                  <div className="flex justify-end space-x-2">
                    <button
                      onClick={() => handleEditDoctor(doctor)}
                      className="px-3 py-1.5 text-blue-600 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-lg transition-colors text-sm font-medium"
                    >
                      <i className="fas fa-edit mr-1"></i>
                      Editar
                    </button>
                    <button
                      onClick={() => handleDeleteDoctor(doctor.id)}
                      className="px-3 py-1.5 text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors text-sm font-medium"
                    >
                      <i className="fas fa-trash mr-1"></i>
                      Eliminar
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      ) : (
        /* List View */
        <div className="bg-white dark:bg-gray-800 rounded-lg shadow overflow-hidden">
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200 dark:divide-gray-700">
              <thead className="bg-gray-50 dark:bg-gray-900">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    Nombre
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    Especialidad
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    ID
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    Usuario Asignado
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                    Acciones
                  </th>
                </tr>
              </thead>
              <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">
                {currentDoctors.map((doctor) => {
            const assignedUser = clerkUsers.find(u => u.id === doctor.user_id);
            return (
                  <tr key={doctor.id} className="hover:bg-gray-50 dark:hover:bg-gray-700">
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="text-sm font-medium text-gray-900 dark:text-white">
                        {doctor.name}
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200">
                        {doctor.specialty}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400">
                      {doctor.id}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 dark:text-gray-400">
                      {doctor.user_id ? (
                        <UserAvatar
                          userId={assignedUser?.id}
                          firstName={assignedUser?.firstName}
                          lastName={assignedUser?.lastName}
                          emailAddress={assignedUser?.emailAddress}
                          profileImageUrl={assignedUser?.profileImageUrl}
                          size="md"
                          showName={true}
                          showEmail={true}
                        />
                      ) : (
                        <UserAvatar
                          size="md"
                          showName={true}
                          showEmail={true}
                        />
                      )}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                      <button
                        onClick={() => handleEditDoctor(doctor)}
                        className="text-blue-600 dark:text-blue-400 hover:text-blue-900 dark:hover:text-blue-300 mr-3"
                      >
                        <i className="fas fa-edit"></i>
                      </button>
                      <button
                        onClick={() => handleDeleteDoctor(doctor.id)}
                        className="text-red-600 dark:text-red-400 hover:text-red-900 dark:hover:text-red-300"
                      >
                        <i className="fas fa-trash"></i>
                      </button>
                    </td>
                  </tr>
                );
              })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Pagination Footer */}
      <div className="mt-6 bg-white dark:bg-gray-800 rounded-lg shadow border border-gray-200 dark:border-gray-700 p-4">
        <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
          <div className="text-sm text-gray-700 dark:text-gray-300">
            Mostrando <span className="font-medium">{startIndex + 1}</span> a{' '}
            <span className="font-medium">{Math.min(endIndex, totalDoctors)}</span> de{' '}
            <span className="font-medium">{totalDoctors}</span> doctores
          </div>

          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2">
              <label className="text-sm font-medium text-gray-700 dark:text-gray-300">Registros por página:</label>
              <select
                value={recordsPerPagePref}
                onChange={(e) => handleRecordsPerPageChange(Number(e.target.value))}
                className="px-3 py-1 border border-gray-300 dark:border-gray-600 rounded-md focus:outline-none focus:ring-2 focus:ring-teal-500 dark:bg-gray-700 dark:text-white text-sm"
              >
                <option value={10}>10</option>
                <option value={25}>25</option>
                <option value={50}>50</option>
                <option value={100}>100</option>
              </select>
            </div>

            <div className="flex items-center gap-1">
              <button
                onClick={() => handlePageChange(currentPage - 1)}
                disabled={currentPage === 1}
                className="px-3 py-1 text-sm border border-gray-300 dark:border-gray-600 rounded-md hover:bg-gray-50 dark:hover:bg-gray-700 disabled:opacity-50 disabled:cursor-not-allowed dark:bg-gray-700 dark:text-white"
              >
                <i className="fas fa-chevron-left"></i>
              </button>

              {getPaginationNumbers().map((page, index) => (
                <span key={index}>
                  {page === '...' ? (
                    <span className="px-3 py-1 text-sm text-gray-500 dark:text-gray-400">...</span>
                  ) : (
                    <button
                      onClick={() => handlePageChange(page as number)}
                      className={`px-3 py-1 text-sm border rounded-md ${
                        currentPage === page
                          ? 'bg-teal-600 text-white border-teal-600'
                          : 'border-gray-300 dark:border-gray-600 hover:bg-gray-50 dark:hover:bg-gray-700 dark:bg-gray-700 dark:text-white'
                      }`}
                    >
                      {page}
                    </button>
                  )}
                </span>
              ))}

              <button
                onClick={() => handlePageChange(currentPage + 1)}
                disabled={currentPage === totalPages || totalPages === 0}
                className="px-3 py-1 text-sm border border-gray-300 dark:border-gray-600 rounded-md hover:bg-gray-50 dark:hover:bg-gray-700 disabled:opacity-50 disabled:cursor-not-allowed dark:bg-gray-700 dark:text-white"
              >
                <i className="fas fa-chevron-right"></i>
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Summary Statistics */}
      <div className="mt-6 grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow">
          <div className="text-sm font-medium text-gray-500 dark:text-gray-400">Total Doctores</div>
          <div className="text-2xl font-bold text-gray-900 dark:text-white">{doctors.length}</div>
        </div>
        <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow">
          <div className="text-sm font-medium text-gray-500 dark:text-gray-400">Total Especialidades</div>
          <div className="text-2xl font-bold text-gray-900 dark:text-white">{uniqueSpecialties.length}</div>
        </div>
        <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow">
          <div className="text-sm font-medium text-gray-500 dark:text-gray-400">Especialidades Activas</div>
          <div className="text-sm text-gray-900 dark:text-white">
            {uniqueSpecialties.join(', ')}
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useRef, Suspense } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { useTheme } from 'next-themes';
import { PatientService } from '@/services/patientService';
import { Patient } from '@/types/patient';

interface PeriodontalStudy {
  id: number;
  fecha: string;
  notas: string;
  datos: any;
}

interface ToothMeasurement {
  diente: string;
  vestibular: {
    mesial: string;
    medio: string;
    distal: string;
  };
  palatino: {
    mesial: string;
    medio: string;
    distal: string;
  };
  movilidad: string;
  sangrado: boolean;
  placa: boolean;
  observaciones: string;
}

function EstudioPeriodontalContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const { theme, systemTheme } = useTheme();
  const [activeTab, setActiveTab] = useState<'nuevo' | 'guardados'>('nuevo');
  const [patient, setPatient] = useState<Patient | null>(null);
  const [patientLoading, setPatientLoading] = useState(true);

  const pacienteId = searchParams.get('paciente_id');
  const [formData, setFormData] = useState({
    patientName: '',
    date: new Date().toISOString().split('T')[0],
    doctor: '',
    indicePlaca: '',
    indiceSangrado: '',
    nivelInsercion: '',
    furcaciones: 'no-evaluado',
    observacionesGenerales: '',
    profilaxis: false,
    raspaje: false,
    cirugia: false,
    mantenimiento: false,
    otro: false,
    otroEspecificar: ''
  });

  const [toothMeasurements, setToothMeasurements] = useState<ToothMeasurement[]>([]);
  const [deletedRowsStack, setDeletedRowsStack] = useState<any[]>([]);
  const [savedStudies, setSavedStudies] = useState<PeriodontalStudy[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [dateFilter, setDateFilter] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [loading, setLoading] = useState(false);

  const teeth = [
    // Upper right (1-8)
    '18', '17', '16', '15', '14', '13', '12', '11',
    // Upper left (9-16)
    '21', '22', '23', '24', '25', '26', '27', '28',
    // Lower left (17-24)
    '38', '37', '36', '35', '34', '33', '32', '31',
    // Lower right (25-32)
    '41', '42', '43', '44', '45', '46', '47', '48'
  ];

  // Animation refs
  const tabsRef = useRef<HTMLDivElement>(null);
  const formRef = useRef<HTMLFormElement>(null);
  const studiesListRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Initialize tooth measurements
    const initialMeasurements: ToothMeasurement[] = teeth.map(tooth => ({
      diente: tooth,
      vestibular: { mesial: '', medio: '', distal: '' },
      palatino: { mesial: '', medio: '', distal: '' },
      movilidad: '0',
      sangrado: false,
      placa: false,
      observaciones: ''
    }));
    setToothMeasurements(initialMeasurements);

    // Load saved studies (mock data for now)
    loadSavedStudies();
  }, []);

  // Load patient data if paciente_id is provided
  useEffect(() => {
    const loadPatientData = async () => {
      if (pacienteId) {
        try {
          const patientData = await PatientService.getPatientById(pacienteId);
          setPatient(patientData);
          setFormData(prev => ({
            ...prev,
            patientName: patientData.nombre_completo
          }));
        } catch (error) {
          console.error('Error loading patient data:', error);
        } finally {
          setPatientLoading(false);
        }
      } else {
        setPatientLoading(false);
      }
    };

    loadPatientData();
  }, [pacienteId]);

  const loadSavedStudies = async () => {
    setLoading(true);
    try {
      const params = new URLSearchParams({
        page: currentPage.toString(),
        limit: '5',
        ...(searchTerm && { search: searchTerm }),
        ...(dateFilter && { date: dateFilter })
      });

      const response = await fetch(`/api/estudios-periodontales?${params}`);
      if (!response.ok) throw new Error('Failed to fetch studies');

      const result = await response.json();
      setSavedStudies(result.data || []);
    } catch (error) {
      console.error('Error loading studies:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (field: string, value: any) => {
    setFormData(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const handleToothMeasurementChange = (toothIndex: number, field: string, value: any) => {
    setToothMeasurements(prev => {
      const updated = [...prev];
      if (field.includes('.')) {
        const [parent, child] = field.split('.');
        const parentKey = parent as keyof ToothMeasurement;
        const currentValue = updated[toothIndex][parentKey];

        if (typeof currentValue === 'object' && currentValue !== null) {
          updated[toothIndex] = {
            ...updated[toothIndex],
            [parentKey]: {
              ...currentValue,
              [child]: value
            }
          };
        }
      } else {
        updated[toothIndex] = {
          ...updated[toothIndex],
          [field]: value
        };
      }
      return updated;
    });
  };

  const deleteToothRow = (index: number) => {
    const row = toothMeasurements[index];
    setDeletedRowsStack(prev => [...prev, { row, index }]);
    setToothMeasurements(prev => prev.filter((_, i) => i !== index));
  };

  const restoreLastDeletedRow = () => {
    if (deletedRowsStack.length > 0) {
      const { row, index } = deletedRowsStack[deletedRowsStack.length - 1];
      setToothMeasurements(prev => {
        const updated = [...prev];
        updated.splice(index, 0, row);
        return updated;
      });
      setDeletedRowsStack(prev => prev.slice(0, -1));
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validate that a patient is selected
    if (!pacienteId && !patient) {
      alert('Por favor seleccione un paciente antes de crear el estudio periodontal.');
      return;
    }

    if (!confirm('¿Está seguro que desea guardar este estudio periodontal?')) {
      return;
    }

    try {
      const studyData = {
        paciente_id: pacienteId || patient?.paciente_id, // Use the actual patient ID
        doctor_id: formData.doctor || null,
        fecha_estudio: formData.date,
        indice_placa: formData.indicePlaca ? parseFloat(formData.indicePlaca) : null,
        indice_sangrado: formData.indiceSangrado ? parseFloat(formData.indiceSangrado) : null,
        nivel_insercion_clinica: formData.nivelInsercion || null,
        furcaciones: formData.furcaciones || 'no-evaluado',
        observaciones_generales: formData.observacionesGenerales || null,
        plan_tratamiento: {
          profilaxis: formData.profilaxis,
          raspaje: formData.raspaje,
          cirugia: formData.cirugia,
          mantenimiento: formData.mantenimiento,
          otro: formData.otro,
          otroEspecificar: formData.otroEspecificar
        },
        mediciones: toothMeasurements
      };

      const response = await fetch('/api/estudios-periodontales', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(studyData)
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || 'Failed to save study');
      }

      const result = await response.json();
      alert('Estudio periodontal guardado correctamente');

      // Reset form or redirect
      setFormData({
        patientName: '',
        date: new Date().toISOString().split('T')[0],
        doctor: '',
        indicePlaca: '',
        indiceSangrado: '',
        nivelInsercion: '',
        furcaciones: 'no-evaluado',
        observacionesGenerales: '',
        profilaxis: false,
        raspaje: false,
        cirugia: false,
        mantenimiento: false,
        otro: false,
        otroEspecificar: ''
      });

      // Switch to saved studies tab
      setActiveTab('guardados');
      loadSavedStudies();

    } catch (error) {
      console.error('Error al guardar el estudio:', error);
      alert('Ocurrió un error al guardar el estudio: ' + (error as Error).message);
    }
  };

  const filteredStudies = savedStudies.filter(study => {
    const matchesSearch = !searchTerm || 
      study.fecha.includes(searchTerm) || 
      (study.notas && study.notas.toLowerCase().includes(searchTerm.toLowerCase()));

    const matchesDate = !dateFilter || study.fecha === dateFilter;

    return matchesSearch && matchesDate;
  });

  const studiesPerPage = 5;
  const totalPages = Math.ceil(filteredStudies.length / studiesPerPage);
  const startIndex = (currentPage - 1) * studiesPerPage;
  const endIndex = startIndex + studiesPerPage;
  const currentStudies = filteredStudies.slice(startIndex, endIndex);

  const formatDate = (dateString: string) => {
    if (!dateString) return '';
    return new Date(dateString).toLocaleDateString('es-ES', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };

  return (
    <>
      {/* Tabs */}
      <div ref={tabsRef} className="bg-white dark:bg-gray-800 rounded-lg shadow-sm">
          <div className="border-b border-gray-200 dark:border-gray-700">
            <nav className="flex -mb-px">
              <button
                onClick={() => setActiveTab('nuevo')}
                className={`tab-button py-3 px-6 border-b-2 font-medium text-sm transition-all duration-200 ${
                  activeTab === 'nuevo'
                    ? 'border-teal-500 text-teal-600 dark:text-teal-400'
                    : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300 hover:border-gray-300'
                }`}
              >
                <i className="fas fa-plus-circle mr-2"></i>
                Nuevo Estudio
              </button>
              <button
                onClick={() => setActiveTab('guardados')}
                className={`tab-button py-3 px-6 border-b-2 font-medium text-sm transition-all duration-200 ${
                  activeTab === 'guardados'
                    ? 'border-teal-500 text-teal-600 dark:text-teal-400'
                    : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300 hover:border-gray-300'
                }`}
              >
                <i className="fas fa-history mr-2"></i>
                Estudios Guardados
              </button>
            </nav>
          </div>

          <div className="p-6">
            {activeTab === 'nuevo' ? (
              /* New Study Form */
              <form ref={formRef} onSubmit={handleSubmit} className="space-y-6 transition-all duration-300 ease-in-out">
                {/* Patient Information */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                      Paciente
                    </label>
                    {patientLoading ? (
                      <div className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-700 text-gray-900 dark:text-white">
                        <div className="animate-pulse">Cargando...</div>
                      </div>
                    ) : patient ? (
                      <div className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md bg-gray-50 dark:bg-gray-600 text-gray-900 dark:text-white">
                        <div className="font-medium">{patient.nombre_completo}</div>
                        <div className="text-sm text-gray-600 dark:text-gray-400">
                          ID: {patient.paciente_id}
                        </div>
                      </div>
                    ) : (
                      <input
                        type="text"
                        value={formData.patientName}
                        onChange={(e) => handleInputChange('patientName', e.target.value)}
                        placeholder="Seleccione un paciente o ingrese el nombre"
                        className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md focus:outline-none focus:ring-2 focus:ring-teal-500 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                        required
                      />
                    )}
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                      Fecha
                    </label>
                    <input
                      type="date"
                      value={formData.date}
                      onChange={(e) => handleInputChange('date', e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md focus:outline-none focus:ring-2 focus:ring-teal-500 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                      Odontólogo
                    </label>
                    <input
                      type="text"
                      value={formData.doctor}
                      onChange={(e) => handleInputChange('doctor', e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md focus:outline-none focus:ring-2 focus:ring-teal-500 bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                      required
                    />
                  </div>
                </div>

                {/* Periodontal Chart */}
                <div>
                  <div className="flex justify-between items-center mb-4">
                    <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                      Chart Periodontal
                    </h3>
                    <button
                      type="button"
                      onClick={restoreLastDeletedRow}
                      disabled={deletedRowsStack.length === 0}
                      className="px-3 py-1 text-sm border border-gray-300 rounded-md hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      <i className="fas fa-undo mr-1"></i>
                      Restaurar Último Diente
                    </button>
                  </div>

                  <div className="overflow-x-auto">
                    <table className="min-w-full border border-gray-200">
                      <thead className="bg-gray-50 dark:bg-gray-700">
                        <tr>
                          <th className="px-2 py-2 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider border-b">
                            Diente
                          </th>
                          <th colSpan={3} className="px-2 py-2 text-center text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider border-b">
                            Vestibular
                          </th>
                          <th colSpan={3} className="px-2 py-2 text-center text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider border-b">
                            Palatino/Lingual
                          </th>
                          <th className="px-2 py-2 text-center text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider border-b">
                            Movilidad
                          </th>
                          <th className="px-2 py-2 text-center text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider border-b">
                            Sangrado
                          </th>
                          <th className="px-2 py-2 text-center text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider border-b">
                            Placa
                          </th>
                          <th className="px-2 py-2 text-left text-xs font-medium text-gray-500 dark:text-gray-300 uppercase tracking-wider border-b">
                            Observaciones
                          </th>
                        </tr>
                        <tr>
                          <th className="px-2 py-1 text-left text-xs font-medium text-gray-500 dark:text-gray-300 border-b"></th>
                          <th className="px-2 py-1 text-center text-xs font-medium text-gray-500 dark:text-gray-300 border-b">Mesial</th>
                          <th className="px-2 py-1 text-center text-xs font-medium text-gray-500 dark:text-gray-300 border-b">Medio</th>
                          <th className="px-2 py-1 text-center text-xs font-medium text-gray-500 dark:text-gray-300 border-b">Distal</th>
                          <th className="px-2 py-1 text-center text-xs font-medium text-gray-500 dark:text-gray-300 border-b">Mesial</th>
                          <th className="px-2 py-1 text-center text-xs font-medium text-gray-500 dark:text-gray-300 border-b">Medio</th>
                          <th className="px-2 py-1 text-center text-xs font-medium text-gray-500 dark:text-gray-300 border-b">Distal</th>
                          <th className="px-2 py-1 text-center text-xs font-medium text-gray-500 dark:text-gray-300 border-b"></th>
                          <th className="px-2 py-1 text-center text-xs font-medium text-gray-500 dark:text-gray-300 border-b"></th>
                          <th className="px-2 py-1 text-center text-xs font-medium text-gray-500 dark:text-gray-300 border-b"></th>
                          <th className="px-2 py-1 text-left text-xs font-medium text-gray-500 dark:text-gray-300 border-b"></th>
                        </tr>
                      </thead>
                      <tbody className="bg-white dark:bg-gray-800 divide-y divide-gray-200 dark:divide-gray-700">
                        {toothMeasurements.map((tooth, index) => (
                          <tr key={tooth.diente} className="hover:bg-gray-50 dark:hover:bg-gray-700">
                            <td className="px-2 py-2">
                              <button
                                type="button"
                                onClick={() => deleteToothRow(index)}
                                className="text-red-600 hover:text-red-800 dark:text-red-400 dark:hover:text-red-600 font-bold cursor-pointer"
                              >
                                {tooth.diente}
                              </button>
                            </td>
                            {/* Vestibular */}
                            <td className="px-1 py-2">
                              <input
                                type="number"
                                min="0"
                                max="20"
                                step="0.5"
                                value={tooth.vestibular.mesial}
                                onChange={(e) => handleToothMeasurementChange(index, 'vestibular.mesial', e.target.value)}
                                className="w-full px-1 py-1 text-center border border-gray-300 dark:border-gray-600 rounded bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                              />
                            </td>
                            <td className="px-1 py-2">
                              <input
                                type="number"
                                min="0"
                                max="20"
                                step="0.5"
                                value={tooth.vestibular.medio}
                                onChange={(e) => handleToothMeasurementChange(index, 'vestibular.medio', e.target.value)}
                                className="w-full px-1 py-1 text-center border border-gray-300 dark:border-gray-600 rounded bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                              />
                            </td>
                            <td className="px-1 py-2">
                              <input
                                type="number"
                                min="0"
                                max="20"
                                step="0.5"
                                value={tooth.vestibular.distal}
                                onChange={(e) => handleToothMeasurementChange(index, 'vestibular.distal', e.target.value)}
                                className="w-full px-1 py-1 text-center border border-gray-300 dark:border-gray-600 rounded bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                              />
                            </td>
                            {/* Palatino/Lingual */}
                            <td className="px-1 py-2">
                              <input
                                type="number"
                                min="0"
                                max="20"
                                step="0.5"
                                value={tooth.palatino.mesial}
                                onChange={(e) => handleToothMeasurementChange(index, 'palatino.mesial', e.target.value)}
                                className="w-full px-1 py-1 text-center border border-gray-300 dark:border-gray-600 rounded bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                              />
                            </td>
                            <td className="px-1 py-2">
                              <input
                                type="number"
                                min="0"
                                max="20"
