                className="w-full bg-green-500 hover:bg-green-600 text-white px-4 py-2 rounded-lg transition-colors flex items-center justify-center"
              >
                <i className="fas fa-file-code mr-2"></i>
                Exportar como JSON
              </button>
              <button
                onClick={() => setShowExportModal(false)}
                className="w-full bg-gray-500 hover:bg-gray-600 text-white px-4 py-2 rounded-lg transition-colors"
              >
                Cancelar
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Improved Medical Warning Modal */}
      <MedicalWarningModal 
        patient={patient}
        isOpen={showWarningModal}
        onClose={() => setShowWarningModal(false)}
      />
    </div>
  );
}

'use client';
// Force dynamic rendering for this page
export const dynamic = 'force-dynamic';

import { useState, useEffect, Suspense } from 'react';
import { useUser } from '@clerk/nextjs';
import { useRouter, useSearchParams } from 'next/navigation';
import { useHistoricalMode } from '@/contexts/HistoricalModeContext';
import { Patient } from '@/types/patient';
import { Quote, QuoteItem } from '@/types/quote';
import { Treatment } from '@/types/treatment';
import { Odontogram, DienteData } from '@/types/odontogram';
import AnimatedWhatsApp from '@/components/AnimatedWhatsApp';
import AnimatedRubish from '@/components/AnimatedRubish';

// Define Promotion interface
interface Promotion {
  id: number;
  codigo: string;
  nombre: string;
  descuento: number;
  precio_original: number;
  precio_promocional: number;
  moneda: string;
  notas?: string;
  fecha_inicio: string;
  fecha_fin: string;
  activo: boolean;
  veces_realizado: number;
  es_grupal?: boolean;
  tipo_promocion?: 'individual' | '2x1' | 'family' | 'friends';
  max_beneficiarios?: number;
}

export default function PresupuestosPage() {
  return (
    <Suspense fallback={
      <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-gray-900">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    }>
      <PresupuestosPageContent />
