          type: 'number'
        },
        {
          key: 'email_notifications',
          value: true,
          description: 'Notificaciones por email',
          category: 'email',
          type: 'boolean'
        },
        // Security Settings
        {
          key: 'session_timeout',
          value: 30,
          description: 'Tiempo de sesión (minutos)',
          category: 'security',
          type: 'number'
        },
        {
          key: 'password_min_length',
