                                 attachment.attachment_type === 'consent' ? 'Consentimiento' :
                                 attachment.attachment_type === 'odontogram' ? 'Odontograma' :
                                 attachment.attachment_type === 'event' ? 'Evento' :
                                 attachment.attachment_type === 'document' ? 'Documento' :
