                            <span className={`px-2 py-1 rounded-full text-xs font-medium ${PaymentService.getPaymentStatusBadge(paymentSummary.estado_pago)}`}>
                              {PaymentService.getPaymentStatusText(paymentSummary.estado_pago)}
