export default function TratamientosPage() {
  const { userRole } = useRoleBasedAccess();

  // Check if user has permission to access treatments
  if (!userRole || (userRole !== 'admin' && userRole !== 'doctor' && userRole !== 'tech_support')) {
    return (
      <AccessDenied
        title="Acceso Denegado"
        message="No tienes permisos para acceder a la gestión de tratamientos."
        explanation="Esta área es exclusiva para administradores, doctores y personal de soporte técnico que pueden gestionar tratamientos activos."
        contactInfo="Si necesitas acceso, contacta a un administrador del sistema."
        onGoBack={() => window.history.back()}
      />
    );
  }

  const { resolvedTheme } = useTheme();
  const [treatments, setTreatments] = useState<Treatment[]>([]);
  const [promotions, setPromotions] = useState<Promotion[]>([]);
  const [paquetes, setPaquetes] = useState<Paquete[]>([]);
  const [activeTab, setActiveTab] = useState<'tratamientos' | 'promociones' | 'paquetes'>('tratamientos');
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [showAddModal, setShowAddModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [selectedTreatment, setSelectedTreatment] = useState<Treatment | null>(null);
  const [selectedPromotion, setSelectedPromotion] = useState<Promotion | null>(null);
  const [selectedPaquete, setSelectedPaquete] = useState<Paquete | null>(null);
  const [selectedTreatments, setSelectedTreatments] = useState<TreatmentItem[]>([]);

  // Form data states
  const [treatmentFormData, setTreatmentFormData] = useState<Treatment>({
    codigo: '',
    nombre: '',
    especialidad: '',
    precio: 0,
    moneda: 'HNL',
    notas: '',
    veces_realizado: 0,
    activo: true
  });
  const [promotionFormData, setPromotionFormData] = useState<Promotion>({
    codigo: '',
    nombre: '',
    descuento: 0,
    precio_original: 0,
    precio_promocional: 0,
    moneda: 'HNL',
    fecha_inicio: '',
    fecha_fin: '',
    activo: true,
    veces_realizado: 0,
  });
  const [paqueteFormData, setPaqueteFormData] = useState<Paquete>({
    codigo: '',
    nombre: '',
    descripcion: '',
    precio_total: 0,
    moneda: 'HNL',
    max_pacientes: 1,
    veces_vendido: 0,
    activo: true,
  });
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [recordsPerPagePref, setRecordsPerPagePref] = useState(25);
  const [currentPage, setCurrentPage] = useState(1);
  const [sortBy, setSortBy] = useState<'nombre' | 'especialidad' | 'precio' | 'veces_realizado'>('nombre');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('asc');

  // Treatment usage modal state
  const [showUsageModal, setShowUsageModal] = useState(false);
  const [selectedTreatmentUsage, setSelectedTreatmentUsage] = useState<Treatment | null>(null);
  const [treatmentUsageData, setTreatmentUsageData] = useState<any[]>([]);
  const [loadingUsageData, setLoadingUsageData] = useState(false);
  // Autocomplete states
  const [codigoSuggestions, setCodigoSuggestions] = useState<string[]>([]);
  const [showCodigoSuggestions, setShowCodigoSuggestions] = useState(false);
  const [promotionCodigoSuggestions, setPromotionCodigoSuggestions] = useState<string[]>([]);
  const [showPromotionCodigoSuggestions, setShowPromotionCodigoSuggestions] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const router = useRouter();
  const { preferences: pagePrefs, loading: prefsLoading, updatePreferences: updatePagePrefs } = usePagePreferences('tratamientos');

  // List of dental specialties
  const specialties = [
    'Odontología General',
    'Ortodoncia',
    'Endodoncia',
    'Periodoncia',
    'Cirugía Oral y Maxilofacial',
    'Odontopediatría',
    'Rehabilitación Oral',
    'Implantología',
    'Operatoria',
    'Estetica',
    'Patología Bucal',
    'Radiología Dental',
    'Sal Pública Dental'
  ];

  useEffect(() => {
    loadTreatments();
    loadPromotions();
    loadPaquetes();
  }, []);

  const loadTreatments = async () => {
    setLoading(true);
    try {
      const response = await fetch('/api/tratamientos');
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setTreatments(data);
    } catch (error) {
      console.error('Error loading treatments:', error);
      // Set empty array if API fails
      setTreatments([]);
    } finally {
      setLoading(false);
    }
  };

  const loadPromotions = async () => {
    try {
      const response = await fetch('/api/promociones');
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setPromotions(data);
    } catch (error) {
      console.error('Error loading promotions:', error);
      // Set empty array if API fails
      setPromotions([]);
    }
  };

  const loadPaquetes = async () => {
    try {
      const response = await fetch('/api/paquetes');
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setPaquetes(data);
    } catch (error) {
      console.error('Error loading paquetes:', error);
      // Set empty array if API fails
      setPaquetes([]);
    }
  };

  // Initialize preferences from pagePrefs
  useEffect(() => {
    if (pagePrefs && !prefsLoading) {
      // Only set if different from current value to avoid unnecessary re-renders
      if (pagePrefs.viewMode && pagePrefs.viewMode !== viewMode) {
        setViewMode(pagePrefs.viewMode);
      }
      if (pagePrefs.recordsPerPage && pagePrefs.recordsPerPage !== recordsPerPagePref) {
        setRecordsPerPagePref(pagePrefs.recordsPerPage);
      }
      if (pagePrefs.sortBy && pagePrefs.sortBy !== sortBy) {
        setSortBy(pagePrefs.sortBy);
      }
      if (pagePrefs.sortOrder && pagePrefs.sortOrder !== sortOrder) {
        setSortOrder(pagePrefs.sortOrder);
      }
    }
  }, [pagePrefs, prefsLoading]); // Remove state variables from dependencies

  // Save preferences with debouncing
  useEffect(() => {
    if (!prefsLoading && pagePrefs?.viewMode !== viewMode) {
      const timeoutId = setTimeout(() => updatePagePrefs({ viewMode }), 500);
      return () => clearTimeout(timeoutId);
    }
  }, [viewMode, prefsLoading, updatePagePrefs]);

  useEffect(() => {
    if (!prefsLoading && recordsPerPagePref) {
      const timeoutId = setTimeout(() => {
        updatePagePrefs({ recordsPerPage: recordsPerPagePref });
      }, 500);
      return () => clearTimeout(timeoutId);
    }
  }, [recordsPerPagePref, prefsLoading, updatePagePrefs]);

  useEffect(() => {
    if (!prefsLoading) {
      const timeoutId = setTimeout(() => {
        updatePagePrefs({ sortBy });
      }, 500);
      return () => clearTimeout(timeoutId);
    }
  }, [sortBy, prefsLoading, updatePagePrefs]);

  useEffect(() => {
    if (!prefsLoading) {
      const timeoutId = setTimeout(() => updatePagePrefs({ sortOrder }), 500);
      return () => clearTimeout(timeoutId);
    }
  }, [sortOrder, prefsLoading, updatePagePrefs]);

  const filteredTreatments = treatments.filter(treatment =>
    treatment.nombre?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    treatment.codigo?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    treatment.especialidad?.toLowerCase().includes(searchTerm.toLowerCase())
  ).sort((a, b) => {
    let comparison = 0;

    switch (sortBy) {
      case 'nombre':
        comparison = (a.nombre || '').localeCompare(b.nombre || '');
        break;
      case 'especialidad':
        comparison = (a.especialidad || '').localeCompare(b.especialidad || '');
        break;
      case 'precio':
        comparison = (a.precio || 0) - (b.precio || 0);
        break;
      case 'veces_realizado':
        comparison = (a.veces_realizado || 0) - (b.veces_realizado || 0);
        break;
    }

    return sortOrder === 'asc' ? comparison : -comparison;
  });

  const filteredPromotions = promotions.filter(promotion =>
    promotion.nombre?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    promotion.codigo?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredPaquetes = paquetes.filter(paquete =>
    paquete.nombre?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    paquete.codigo?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Pagination calculations
  const currentData = activeTab === 'tratamientos' ? filteredTreatments : 
                     activeTab === 'promociones' ? filteredPromotions : 
                     filteredPaquetes;
  const totalRecords = currentData.length;
  const totalPages = Math.ceil(totalRecords / recordsPerPagePref);
  const startIndex = (currentPage - 1) * recordsPerPagePref;
  const endIndex = startIndex + recordsPerPagePref;
  const paginatedData = currentData.slice(startIndex, endIndex);

  // Reset to page 1 when search term, records per page, sort by, or sort order changes
  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, recordsPerPagePref, sortBy, sortOrder]);

  // Function to load treatment usage data
  const loadTreatmentUsageData = async (treatmentId: number, treatmentData: Treatment) => {
    setLoadingUsageData(true);
    try {
      const { data: completedTreatments, error } = await supabase
        .from('tratamientos_realizados')
        .select(`
          *,
          tratamientos_completados!inner(
            id,
            paciente_id,
            fecha_cita,
            patients!inner(
              nombre_completo,
              numero_identidad,
              telefono,
              codigopais
            )
          )
        `)
        .eq('tratamiento_id', treatmentId);

      if (error) throw error;

      const treatmentUsage = await Promise.all(
        (completedTreatments || []).map(async (item) => {
          const { data: payments, error: paymentError } = await supabase
            .from('payments')
            .select('monto_pago, moneda')
            .eq('tratamiento_completado_id', item.tratamientos_completados.id);

          const totalPaid = payments?.reduce((sum, payment) => sum + payment.monto_pago, 0) || 0;

          return {
            patientName: item.tratamientos_completados.patients.nombre_completo,
            identificacion: item.tratamientos_completados.patients.numero_identidad || 'Sin identificación',
            phone: item.tratamientos_completados.patients.telefono,
            countryCode: item.tratamientos_completados.patients.codigopais,
            amountPaid: totalPaid,
            currency: payments?.[0]?.moneda || 'HNL',
            treatmentAmount: treatmentData?.precio || 0,
            treatmentCurrency: treatmentData?.moneda || 'HNL',
            date: item.tratamientos_completados.fecha_cita
          };
        })
      );

      setTreatmentUsageData(treatmentUsage);
    } catch (error) {
      console.error('Error loading treatment usage data:', error);
      setTreatmentUsageData([]);
    } finally {
      setLoadingUsageData(false);
    }
  };

  // Function to open usage modal
  const openUsageModal = (treatment: Treatment) => {
    setSelectedTreatmentUsage(treatment);
    setShowUsageModal(true);
    setTreatmentUsageData([]); // Clear previous data
    loadTreatmentUsageData(treatment.id, treatment);
  };
  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, recordsPerPagePref, activeTab]);

  const handlePageChange = (page: number) => {
    setCurrentPage(page);
  };

  const handleRecordsPerPageChange = (value: number) => {
    setRecordsPerPagePref(value);
  };

  const getPaginationNumbers = () => {
    const pages = [];
    const maxVisiblePages = 5;

    if (totalPages <= maxVisiblePages) {
      for (let i = 1; i <= totalPages; i++) {
        pages.push(i);
      }
    } else {
      if (currentPage <= 3) {
        for (let i = 1; i <= 4; i++) {
          pages.push(i);
        }
        pages.push('...');
        pages.push(totalPages);
      } else if (currentPage >= totalPages - 2) {
        pages.push(1);
        pages.push('...');
        for (let i = totalPages - 3; i <= totalPages; i++) {
          pages.push(i);
        }
      } else {
        pages.push(1);
        pages.push('...');
        for (let i = currentPage - 1; i <= currentPage + 1; i++) {
          pages.push(i);
        }
        pages.push('...');
        pages.push(totalPages);
      }
    }

    return pages;
  };

  const handleAddTreatment = () => {
    setSelectedTreatment(null);
    setSelectedPromotion(null);
    setTreatmentFormData({
      codigo: '',
      nombre: '',
      especialidad: '',
      precio: 0,
      moneda: 'HNL',
      notas: '',
      veces_realizado: 0,
      activo: true
    });
    setShowAddModal(true);
  };

  const handleAddPromotion = async () => {
    setSelectedTreatment(null);
    setSelectedPromotion(null);
    setPromotionFormData({
      codigo: '',
      nombre: '',
      descuento: 0,
      precio_original: 0,
      precio_promocional: 0,
      moneda: 'HNL', // Default currency
      fecha_inicio: '',
      fecha_fin: '',
      activo: true,
      veces_realizado: 0, // Reset counter to 0 for new promotions
    });

    // Auto-generate promotion code
    try {
      const nextCode = await TreatmentService.generateNextPromotionCode();
      setPromotionFormData(prev => ({ ...prev, codigo: nextCode }));
    } catch (error) {
      console.error('Error generating next promotion code:', error);
    }

    setShowAddModal(true);
  };

  const handleEditTreatment = (treatment: Treatment) => {
    setSelectedTreatment(treatment);
    setSelectedPromotion(null);
    setTreatmentFormData({
      codigo: treatment.codigo,
      nombre: treatment.nombre,
      especialidad: treatment.especialidad || '',
      precio: treatment.precio,
      moneda: treatment.moneda || 'HNL',
      notas: treatment.notas || '',
      veces_realizado: treatment.veces_realizado || 0,
      activo: treatment.activo !== false
    });
    // Clear autocomplete suggestions when editing
    setShowCodigoSuggestions(false);
    setCodigoSuggestions([]);
    setShowAddModal(true);
  };

  const handleEditPromotion = (promotion: Promotion) => {
    setSelectedPromotion(promotion);
    setSelectedTreatment(null);
    setPromotionFormData({
      codigo: promotion.codigo || '',
      nombre: promotion.nombre || '',
      descuento: promotion.descuento || 0,
      precio_original: promotion.precio_original || 0,
      precio_promocional: promotion.precio_promocional || 0,
      moneda: promotion.moneda || 'HNL',
      fecha_inicio: promotion.fecha_inicio || '',
      fecha_fin: promotion.fecha_fin || '',
      veces_realizado: promotion.veces_realizado || 0,
      activo: promotion.activo !== undefined ? promotion.activo : true
    });
    setShowAddModal(true);
  };

  const handleDeleteTreatment = (treatment: Treatment) => {
    setSelectedTreatment(treatment);
    setSelectedPromotion(null);
    setShowDeleteModal(true);
  };

  const handleDeletePromotion = (promotion: Promotion) => {
    setSelectedPromotion(promotion);
    setSelectedTreatment(null);
    setShowDeleteModal(true);
  };

  // Paquete handlers
  const handleAddPaquete = async () => {
    setSelectedTreatment(null);
    setSelectedPromotion(null);
    setSelectedPaquete(null);

    // Reset form data for new paquete
    setPaqueteFormData({
      codigo: '',
      nombre: '',
      descripcion: '',
      precio_total: 0,
      moneda: 'HNL',
      max_pacientes: 1,
      veces_vendido: 0,
      activo: true,
    });

    // Auto-generate paquete code
    try {
      const nextCode = await TreatmentService.generateNextPaqueteCode();
      setPaqueteFormData(prev => ({ ...prev, codigo: nextCode }));
    } catch (error) {
      console.error('Error generating next paquete code:', error);
    }

    setShowAddModal(true);
  };

  const handleEditPaquete = (paquete: Paquete) => {
    setSelectedTreatment(null);
    setSelectedPromotion(null);
    setSelectedPaquete(paquete);

    // Set form data with existing paquete data
    setPaqueteFormData({
      codigo: paquete.codigo,
      nombre: paquete.nombre,
      descripcion: paquete.descripcion || '',
      precio_total: paquete.precio_total,
      moneda: paquete.moneda,
      max_pacientes: paquete.max_pacientes,
      veces_vendido: paquete.veces_vendido,
      activo: paquete.activo !== false,
    });

    // Add paquete to selected treatments for form submission
    setSelectedTreatments([{
      id: paquete.id.toString(),
      tratamiento_completado_id: '', // Will be set when treatment is completed
      tratamiento_id: paquete.id,
      nombre_tratamiento: paquete.nombre,
      codigo_tratamiento: paquete.codigo,
      precio_original: paquete.precio_total,
      precio_final: paquete.precio_total,
      moneda: paquete.moneda,
      cantidad: 1,
      notas: paquete.descripcion || '',
      doctor_id: null,
      doctor_name: null
    }]);

    setShowAddModal(true);
  };

  const handleDeletePaquete = (paquete: Paquete) => {
    setSelectedTreatment(null);
    setSelectedPromotion(null);
    setSelectedPaquete(paquete);
    setShowDeleteModal(true);
  };

  // Autocomplete function for codigo
  const handleCodigoChange = (value: string) => {
    setTreatmentFormData({ ...treatmentFormData, codigo: value });

    if (value.length >= 2) {
      // Filter existing treatments based on codigo
      const suggestions = treatments
        .filter(t => t.codigo.toLowerCase().includes(value.toLowerCase()))
        .map(t => t.codigo)
        .slice(0, 5); // Limit to 5 suggestions

      setCodigoSuggestions(suggestions);
      setShowCodigoSuggestions(suggestions.length > 0);
    } else {
      setCodigoSuggestions([]);
      setShowCodigoSuggestions(false);
    }
  };

  const handleCodigoSelect = (codigo: string) => {
    const treatment = treatments.find(t => t.codigo === codigo);
    if (treatment) {
      setTreatmentFormData({
        codigo: treatment.codigo,
        nombre: treatment.nombre,
        especialidad: treatment.especialidad || '',
        precio: treatment.precio,
        moneda: treatment.moneda,
        notas: treatment.notas || '',
        veces_realizado: treatment.veces_realizado,
        activo: treatment.activo !== false
      });
    }
    setShowCodigoSuggestions(false);
    setCodigoSuggestions([]);
  };

  // Autocomplete function for promotion codigo
  const handlePromotionCodigoChange = (value: string) => {
    setPromotionFormData({ ...promotionFormData, codigo: value });

    if (value.length >= 2) {
      // Filter existing promotions based on codigo
      const suggestions = promotions
        .filter(p => p.codigo.toLowerCase().includes(value.toLowerCase()))
        .map(p => p.codigo)
        .slice(0, 5); // Limit to 5 suggestions

      setPromotionCodigoSuggestions(suggestions);
      setShowPromotionCodigoSuggestions(suggestions.length > 0);
    } else {
      setPromotionCodigoSuggestions([]);
      setShowPromotionCodigoSuggestions(false);
    }
  };

  const handlePromotionCodigoSelect = (codigo: string) => {
    const promotion = promotions.find(p => p.codigo === codigo);
    if (promotion) {
      setPromotionFormData({
        codigo: promotion.codigo,
        nombre: promotion.nombre,
        descuento: promotion.descuento,
        precio_original: promotion.precio_original,
        precio_promocional: promotion.precio_promocional,
        moneda: promotion.moneda,
        fecha_inicio: promotion.fecha_inicio,
        fecha_fin: promotion.fecha_fin,
        activo: promotion.activo,
        veces_realizado: promotion.veces_realizado
      });
    }
    setShowPromotionCodigoSuggestions(false);
    setPromotionCodigoSuggestions([]);
  };

  // Handle specialty change to auto-generate code for new treatments
  const handleSpecialtyChange = async (newSpecialty: string) => {
    setTreatmentFormData({ ...treatmentFormData, especialidad: newSpecialty });

    // Only auto-generate code for new treatments (not edits)
    if (!selectedTreatment && newSpecialty) {
      try {
        const nextCode = await TreatmentService.generateNextCode(newSpecialty);
        setTreatmentFormData(prev => ({ ...prev, codigo: nextCode }));
      } catch (error) {
        console.error('Error generating next code:', error);
      }
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      if (activeTab === 'tratamientos') {
        const treatmentData = {
          codigo: treatmentFormData.codigo || '',
          nombre: treatmentFormData.nombre || '',
          especialidad: treatmentFormData.especialidad || '',
          precio: treatmentFormData.precio || 0,
          moneda: treatmentFormData.moneda || 'HNL',
          notas: treatmentFormData.notas || '',
          veces_realizado: treatmentFormData.veces_realizado || 0,
          activo: treatmentFormData.activo !== false
        };

