'use client';

import React, { useRef, useEffect, useState } from 'react';
import SignaturePad from 'signature_pad';
import { useTheme } from '@/contexts/ThemeContext';

interface SignaturePadComponentProps {
  onChange: (signatureData: string | null) => void;
  value?: string | null;
  disabled?: boolean;
}

export default function SignaturePadComponent({ onChange, value, disabled = false }: SignaturePadComponentProps) {
  const { resolvedTheme } = useTheme();
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const signaturePadRef = useRef<SignaturePad | null>(null);
  const [isEmpty, setIsEmpty] = useState(true);

  useEffect(() => {
    if (canvasRef.current) {
      const canvas = canvasRef.current;

      // Use theme-appropriate colors
      const isDark = resolvedTheme === 'dark';
      const backgroundColor = isDark ? 'rgb(31, 41, 55)' : 'rgb(255, 255, 255)';
      const penColor = isDark ? 'rgb(255, 255, 255)' : 'rgb(0, 0, 0)';

      const signaturePad = new SignaturePad(canvas, {
        backgroundColor,
        penColor,
        // Disable all smoothing that causes stroke issues
        minWidth: 1,
        maxWidth: 2,
        velocityFilterWeight: 0.1,
        dotSize: 2,
        throttle: 0,
      });

      signaturePadRef.current = signaturePad;

      // Simple resize - only on window resize, not during drawing
      const handleResize = () => {
        if (!canvasRef.current || !signaturePadRef.current) return;

        const canvas = canvasRef.current;
        const signaturePad = signaturePadRef.current;

        // Store current signature
        const data = signaturePad.isEmpty() ? null : signaturePad.toData();

        // Set canvas size
        const ratio = Math.max(window.devicePixelRatio || 1, 1);
        canvas.width = canvas.offsetWidth * ratio;
        canvas.height = canvas.offsetHeight * ratio;

        // Scale context
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.scale(ratio, ratio);
          // Fix stroke overlap issues
          ctx.lineCap = 'round';
          ctx.lineJoin = 'round';
          ctx.globalCompositeOperation = 'source-over';
        }

        // Clear and restore signature
        signaturePad.clear();
        if (data) {
          signaturePad.fromData(data);
        }
      };

      // Initial resize
      handleResize();

      // Only listen to window resize events
      window.addEventListener('resize', handleResize);

      // Handle signature events
      signaturePad.addEventListener('beginStroke', () => {
        setIsEmpty(false);
      });

      signaturePad.addEventListener('endStroke', () => {
        const dataURL = signaturePad.toDataURL('image/png');
        onChange(dataURL);
      });

      // Load existing signature if provided
      if (value) {
        if (value.startsWith('data:image/')) {
          signaturePad.fromDataURL(value);
          setIsEmpty(false);
        }
      }

      return () => {
        window.removeEventListener('resize', handleResize);
      };
    }
  }, [onChange, value, resolvedTheme]);

  const clearSignature = () => {
    if (signaturePadRef.current) {
      signaturePadRef.current.clear();
      onChange(null);
      setIsEmpty(true);
    }
  };

  return (
    <div className={`w-full ${disabled ? 'opacity-50 pointer-events-none' : ''}`}>
      <div className="relative">
        <canvas
          ref={canvasRef}
          className={`border-2 rounded-lg w-full ${disabled ? 'cursor-not-allowed' : 'cursor-crosshair'} ${
            resolvedTheme === 'dark' 
              ? 'border-gray-600' 
              : 'border-gray-300'
          }`}
          style={{ 
            touchAction: 'none', 
            height: '225px', // 150px * 1.50 = 225px
            backgroundColor: resolvedTheme === 'dark' ? 'rgb(31, 41, 55)' : 'rgb(255, 255, 255)'
          }}
        />
        {isEmpty && (
          <div className="signature-placeholder absolute inset-0 flex flex-col items-center justify-center pointer-events-none ${
            resolvedTheme === 'dark' ? 'text-gray-400' : 'text-gray-400'
          }">
            <i className="fas fa-signature text-4xl mb-2 opacity-50"></i>
            <span>Por favor, firme aquí</span>
          </div>
        )}
      </div>
      <div className="flex justify-between items-center mt-3">
        <button
          type="button"
          onClick={clearSignature}
          disabled={disabled || isEmpty}
          className="bg-red-500 text-white px-4 py-2 rounded hover:bg-red-600 disabled:bg-gray-400 disabled:cursor-not-allowed transition-colors"
        >
          <i className="fas fa-eraser mr-2"></i>
          Limpiar Firma
        </button>
        <span className="text-sm text-gray-600">
          Firme en el área de arriba
        </span>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { useDebounce } from '@/hooks/useDebounce';

interface IDValidationResult {
  isUnique: boolean;
  existingPatient?: {
    id: string;
    name: string;
    idNumber: string;
  };
  message: string;
  isValid: boolean; // Overall validity (unique OR matches current patient)
}

interface SmartIDValidationProps {
  idNumber: string;
  originalIdNumber?: string; // Original ID for edit mode
  patientId?: string; // For edit mode
  onValidationChange?: (result: IDValidationResult) => void;
  disabled?: boolean;
  className?: string;
}

export default function SmartIDValidation({ 
  idNumber, 
  originalIdNumber,
  patientId, 
  onValidationChange,
  disabled = false,
  className = ''
}: SmartIDValidationProps) {
  const [validationResult, setValidationResult] = useState<IDValidationResult | null>(null);
  const [isValidating, setIsValidating] = useState(false);
const [hasBeenValidated, setHasBeenValidated] = useState(false);

  // Debounce the ID number to avoid excessive API calls
  const debouncedIdNumber = useDebounce(idNumber, 500);

  const validateID = useCallback(async (idToValidate: string) => {
    if (!idToValidate || idToValidate.length < 3) {
      setValidationResult(null);
      setHasBeenValidated(false);
      onValidationChange?.(null);
      return;
    }

    // If in edit mode and ID hasn't changed, it's automatically valid
    if (originalIdNumber && idToValidate.trim() === originalIdNumber.trim()) {
      setValidationResult({
        isUnique: true,
        isValid: true,
        message: 'Número de ID sin cambios - válido'
      });
      setHasBeenValidated(true);
      onValidationChange?.({
        isUnique: true,
        isValid: true,
        message: 'Número de ID sin cambios - válido'
      });
      return;
    }

    setIsValidating(true);

    try {
      const params = new URLSearchParams({
        id: idToValidate.trim(),
        ...(patientId && { patientId })
      });

      const response = await fetch(`/api/validate-id?${params}`);
      const result = await response.json();

      if (result.success) {
        if (result.isValid && result.isUnique) {
          setValidationResult({
            isUnique: true,
            isValid: true,
            message: 'ID válido y único'
          });
        } else {
          setValidationResult({
            isUnique: false,
            isValid: false,
            message: result.message || 'ID no válido o ya existe'
          });
        }
        setHasBeenValidated(true);
        onValidationChange?.(validationResult);
      } else {
        setValidationResult({
          isUnique: false,
          isValid: false,
          message: 'Error al validar número de ID'
        });
      }
    } catch (error) {
      setValidationResult({
        isUnique: false,
        isValid: false,
        message: 'Error de red al validar ID'
      });
    } finally {
      setIsValidating(false);
    }
  }, [originalIdNumber, patientId, onValidationChange]);

  // Validate when debounced ID changes
  useEffect(() => {
    if (disabled) return;

    if (debouncedIdNumber) {
      validateID(debouncedIdNumber);
    } else {
      setValidationResult(null);
      setHasBeenValidated(false);
      onValidationChange?.(null);
    }
  }, [debouncedIdNumber, validateID, disabled]);

  // Don't show anything if no ID number or too short
  if (!idNumber || idNumber.length < 3) {
    return null;
  }

  // Show validation state
  const getValidationMessage = () => {
    if (isValidating) {
      return {
        text: 'Verificando...',
        color: 'text-blue-600 dark:text-blue-400',
        icon: 'fas fa-spinner fa-spin'
      };
    }

    if (!hasBeenValidated) {
      return null;
    }

    if (validationResult?.isValid) {
      // Check if it's valid because it's unchanged
      if (originalIdNumber && idNumber.trim() === originalIdNumber.trim()) {
        return {
          text: 'Número de ID actual del paciente',
          color: 'text-gray-600 dark:text-gray-400',
          icon: 'fas fa-check-circle'
        };
      }

      // Valid because it's unique
      return {
        text: 'Número de Identificación disponible',
        color: 'text-green-600 dark:text-green-400',
        icon: 'fas fa-check-circle'
      };
    }

    if (validationResult?.existingPatient) {
      return {
        text: `Ya existe para: ${validationResult.existingPatient.name}`,
        color: 'text-red-600 dark:text-red-400',
        icon: 'fas fa-exclamation-triangle'
      };
    }

    return {
      text: validationResult?.message || 'Error verificando',
      color: 'text-red-600 dark:text-red-400',
      icon: 'fas fa-times-circle'
    };
  };

  const validationMessage = getValidationMessage();

  if (!validationMessage) {
    return null;
  }

  return (
    <div className={`mt-1 text-sm flex items-center space-x-2 ${className}`}>
      <i className={`${validationMessage.icon} ${validationMessage.color}`}></i>
      <span className={validationMessage.color}>
        {validationMessage.text}
      </span>
    </div>
  );
}

import React from 'react';
import { TicketActivity, User } from '@/types/ticket';
import { CheckCircle2, MessageSquare, UserPlus, Clock, Settings, AlertCircle, FileText } from 'lucide-react';
import { formatDistanceToNow } from 'date-fns';
import { format } from 'date-fns';

type ActivityWithUser = TicketActivity & { 
  user: User;
};

interface TicketTimelineProps {
  activities: ActivityWithUser[];
  className?: string;
}

export default function TicketTimeline({ activities, className = '' }: TicketTimelineProps) {
  if (!activities || activities.length === 0) {
    return (
      <div className={`text-center py-8 text-gray-500 ${className}`}>
        <Clock className="mx-auto h-12 w-12 text-gray-300 mb-3" />
        <p>No hay actividad registrada</p>
      </div>
    );
  }

  return (
    <div className={`flow-root ${className}`}>
      <ul role="list" className="-mb-8">
        {activities.map((activity, idx) => (
          <li key={activity.id}>
            <div className="relative pb-8">
              {idx !== activities.length - 1 && (
                <span className="absolute left-5 top-5 -ml-px h-full w-0.5 bg-gray-200 dark:bg-gray-700" aria-hidden="true" />
              )}
              <div className="relative flex items-start space-x-3">
                <div className="relative">
                  <ActivityIcon type={activity.activity_type} />
                </div>
                <div className="min-w-0 flex-1">
                  <div className="flex items-center space-x-2">
                    <div className="text-sm">
                      <span className="font-medium text-gray-900 dark:text-gray-100">
                        {activity.user?.name || 'Usuario desconocido'}
                      </span>
                      <span className="text-gray-500 dark:text-gray-400">
                        {activity.user?.role && ` (${activity.user.role})`}
                      </span>
                    </div>
                    <div className="flex items-center text-xs text-gray-500 dark:text-gray-400">
                      <Clock className="h-3 w-3 mr-1" />
                      {formatDistanceToNow(new Date(activity.created_at), { addSuffix: true })}
                      <span className="mx-2">•</span>
                      <span>{format(new Date(activity.created_at), 'MMM d, yyyy HH:mm')}</span>
                    </div>
                  </div>
                  <div className="mt-2 text-sm text-gray-700 dark:text-gray-300">
                    <p className="whitespace-pre-wrap">{activity.content}</p>

                    {/* Show metadata if exists */}
                    {activity.metadata && (
                      <div className="mt-2 p-2 bg-gray-50 dark:bg-gray-800 rounded text-xs">
                        <MetadataDisplay metadata={activity.metadata} />
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}

function ActivityIcon({ type }: { type: string }) {
  const baseClasses = "flex h-10 w-10 items-center justify-center rounded-full ring-8 ring-white dark:ring-gray-900";

  switch (type) {
    case "STATUS_CHANGE":
      return (
        <div className={`${baseClasses} bg-green-100 text-green-600 dark:bg-green-900 dark:text-green-300`}>
          <CheckCircle2 size={18} />
        </div>
      );
    case "ASSIGNMENT":
      return (
        <div className={`${baseClasses} bg-blue-100 text-blue-600 dark:bg-blue-900 dark:text-blue-300`}>
          <UserPlus size={18} />
        </div>
      );
    case "COMMENT":
      return (
        <div className={`${baseClasses} bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-300`}>
          <MessageSquare size={18} />
        </div>
      );
    case "SYSTEM_UPDATE":
      return (
        <div className={`${baseClasses} bg-purple-100 text-purple-600 dark:bg-purple-900 dark:text-purple-300`}>
          <Settings size={18} />
        </div>
      );
    case "TICKET_CREATED":
      return (
        <div className={`${baseClasses} bg-yellow-100 text-yellow-600 dark:bg-yellow-900 dark:text-yellow-300`}>
          <FileText size={18} />
        </div>
      );
    case "ATTACHMENT_ADDED":
      return (
        <div className={`${baseClasses} bg-indigo-100 text-indigo-600 dark:bg-indigo-900 dark:text-indigo-300`}>
          <FileText size={18} />
        </div>
      );
    default:
      return (
        <div className={`${baseClasses} bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-300`}>
          <AlertCircle size={18} />
        </div>
      );
  }
}

function MetadataDisplay({ metadata }: { metadata: Record<string, any> }) {
  if (!metadata || Object.keys(metadata).length === 0) return null;

  const entries = Object.entries(metadata).filter(([_, value]) => 
    value !== null && value !== undefined && value !== ''
  );

  if (entries.length === 0) return null;

  return (
    <div className="space-y-1">
      {entries.map(([key, value]) => (
        <div key={key} className="flex justify-between">
          <span className="font-medium capitalize text-gray-600 dark:text-gray-400">
            {formatMetadataKey(key)}:
          </span>
          <span className="text-gray-800 dark:text-gray-200">
            {formatMetadataValue(value)}
          </span>
        </div>
      ))}
    </div>
  );
}

function formatMetadataKey(key: string): string {
  return key.replace(/_/g, ' ').toLowerCase();
}

function formatMetadataValue(value: any): string {
  if (typeof value === 'object' && value !== null) {
    return JSON.stringify(value, null, 2);
  }
  return String(value);
}

'use client';

import { useState } from 'react';
import { Currency, getCurrencySymbol, getAvailableCurrencies } from '../utils/currencyUtils';

export interface TreatmentFormData {
  id?: number;
  codigo: string;
  nombre: string;
  especialidad: string;
  precio: number;
  moneda: Currency; // New field for currency
  notas?: string; // Notes field for additional treatment information
  veces_realizado: number;
  activo: boolean;
}

export interface PromotionFormData {
  id?: number;
  codigo: string;
  nombre: string;
  descuento: number;
  precio_original: number;
  precio_promocional: number;
  moneda: Currency; // New field for currency
  fecha_inicio: string;
  fecha_fin: string;
  activo: boolean;
  veces_realizado: number;
  es_grupal?: boolean;
  tipo_promocion?: 'individual' | '2x1' | 'family' | 'friends';
  max_beneficiarios?: number;
}

interface TreatmentModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (e: React.FormEvent) => Promise<void>;
  isSubmitting: boolean;
  mode: 'treatment' | 'promotion';
  isEdit: boolean;
  treatmentFormData: TreatmentFormData;
  setTreatmentFormData: (data: TreatmentFormData) => void;
  promotionFormData: PromotionFormData;
  setPromotionFormData: (data: PromotionFormData) => void;
  specialties: string[];
  handleSpecialtyChange: (newSpecialty: string) => Promise<void>;
}

export default function TreatmentModal({
  isOpen,
  onClose,
  onSubmit,
  isSubmitting,
  mode,
  isEdit,
  treatmentFormData,
  setTreatmentFormData,
  promotionFormData,
  setPromotionFormData,
  specialties,
  handleSpecialtyChange
}: TreatmentModalProps) {
  if (!isOpen) return null;

