'use client';

import { useState, useEffect, useCallback } from 'react';

interface Notification {
  id: string;
  title: string;
  message: string;
  type: 'info' | 'warning' | 'error' | 'success';
  timestamp: Date;
  autoClose?: boolean;
  duration?: number;
}

export function NotificationSystem() {
  const [notifications, setNotifications] = useState<Notification[]>([]);

  // Add a new notification
  const addNotification = useCallback((
    title: string,
    message: string,
    type: Notification['type'] = 'info',
    options: { autoClose?: boolean; duration?: number } = {}
  ) => {
    const notification: Notification = {
      id: Date.now().toString(),
      title,
      message,
      type,
      timestamp: new Date(),
      autoClose: options.autoClose ?? true,
      duration: options.duration ?? 5000,
    };

    setNotifications(prev => [...prev, notification]);

    // Auto-close notification if enabled
    if (notification.autoClose) {
      setTimeout(() => {
        removeNotification(notification.id);
      }, notification.duration);
    }

    return notification.id;
  }, []);

  // Remove a notification
  const removeNotification = useCallback((id: string) => {
    setNotifications(prev => prev.filter(n => n.id !== id));
  }, []);

  // Clear all notifications
  const clearNotifications = useCallback(() => {
    setNotifications([]);
  }, []);

  // Expose notification functions to window for global use
  useEffect(() => {
    if (typeof window !== 'undefined') {
      (window as any).addNotification = addNotification;
      (window as any).removeNotification = removeNotification;
      (window as any).clearNotifications = clearNotifications;
    }
  }, [addNotification, removeNotification, clearNotifications]);

  return (
    <div className="fixed top-4 right-4 z-50 space-y-2">
      {notifications.map((notification) => (
        <div
          key={notification.id}
          className={`max-w-sm p-4 rounded-lg shadow-lg border-l-4 transform transition-all duration-300 ease-in-out ${
            notification.type === 'error'
              ? 'bg-red-50 border-red-500 text-red-900'
              : notification.type === 'warning'
              ? 'bg-yellow-50 border-yellow-500 text-yellow-900'
              : notification.type === 'success'
              ? 'bg-green-50 border-green-500 text-green-900'
              : 'bg-blue-50 border-blue-500 text-blue-900'
          }`}
        >
          <div className="flex items-start justify-between">
            <div className="flex-1">
              <h4 className="font-semibold text-sm">{notification.title}</h4>
              <p className="text-sm mt-1 opacity-90">{notification.message}</p>
              <p className="text-xs mt-2 opacity-70">
                {notification.timestamp.toLocaleTimeString()}
              </p>
            </div>
            <button
              onClick={() => removeNotification(notification.id)}
              className="ml-4 text-gray-400 hover:text-gray-600 transition-colors"
            >
              <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>
        </div>
      ))}

      {notifications.length > 0 && (
        <button
          onClick={clearNotifications}
          className="text-xs text-gray-500 hover:text-gray-700 transition-colors"
        >
          Limpiar todas
        </button>
      )}
    </div>
  );
}

'use client';

import { createContext, useContext, useState, ReactNode, useEffect } from 'react';

export interface BellNotification {
  id: string;
  type: 'patient_created' | 'patient_updated' | 'system' | 'calendar_event' | 'calendar_reminder';
  title: string;
  message: string;
  timestamp: Date;
  read: boolean;
  metadata?: {
    patientId?: string;
    userId?: string;
    userName?: string;
    patientName?: string;
    eventId?: string;
    eventTitle?: string;
    eventTime?: Date;
  };
}

interface BellNotificationContextType {
  notifications: BellNotification[];
  unreadCount: number;
  addNotification: (notification: Omit<BellNotification, 'id' | 'timestamp' | 'read'>) => void;
  markAsRead: (id: string) => void;
  markAllAsRead: () => void;
  removeNotification: (id: string) => void;
  clearAll: () => void;
}

const BellNotificationContext = createContext<BellNotificationContextType | undefined>(undefined);

export function BellNotificationProvider({ children }: { children: ReactNode }) {
  const [notifications, setNotifications] = useState<BellNotification[]>([]);

  // Calculate unread count
  const unreadCount = notifications.filter(n => !n.read).length;

  const addNotification = async (notification: Omit<BellNotification, 'id' | 'timestamp' | 'read'>) => {
    try {
      const response = await fetch('/api/notifications', {
        method: 'POST',
        credentials: 'include',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(notification),
      });

      if (response.ok) {
        const newNotification = await response.json();
        setNotifications(prev => [newNotification, ...prev]);
      } else {
        console.error('Failed to add notification, status:', response.status);
      }
    } catch (error) {
      console.error('Error adding notification:', error);
    }
  };

  const markAsRead = async (id: string) => {
    try {
      const response = await fetch('/api/notifications', {
        method: 'PATCH',
        credentials: 'include',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          notificationId: id,
          action: 'markAsRead'
        }),
      });

      if (response.ok) {
        setNotifications(prev => 
          prev.map(n => n.id === id ? { ...n, read: true } : n)
        );
      }
    } catch (error) {
      console.error('Error marking notification as read:', error);
    }
  };

  const markAllAsRead = async () => {
    try {
      const response = await fetch('/api/notifications', {
        method: 'PATCH',
        credentials: 'include',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          action: 'markAllAsRead'
        }),
      });

      if (response.ok) {
        setNotifications(prev => 
          prev.map(n => ({ ...n, read: true }))
        );
      }
    } catch (error) {
      console.error('Error marking all notifications as read:', error);
    }
  };

  const removeNotification = async (id: string) => {
    try {
      const response = await fetch('/api/notifications', {
        method: 'PATCH',
        credentials: 'include',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          notificationId: id,
          action: 'remove'
        }),
      });

      if (response.ok) {
        setNotifications(prev => prev.filter(n => n.id !== id));
      }
    } catch (error) {
      console.error('Error removing notification:', error);
    }
  };

  const clearAll = async () => {
    try {
      const response = await fetch('/api/notifications', {
        method: 'PATCH',
        credentials: 'include',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          action: 'clearAll'
        }),
      });

      if (response.ok) {
        setNotifications([]);
      }
    } catch (error) {
      console.error('Error clearing all notifications:', error);
    }
  };

  // Fetch notifications from server and sync periodically
  useEffect(() => {
    const fetchNotifications = async () => {
      try {
        const response = await fetch('/api/notifications', {
          method: 'GET',
          credentials: 'include', // Include cookies for authentication
          headers: {
            'Content-Type': 'application/json',
          }
        });

        if (response.status === 401) {
          console.error('🔔 Authentication failed - user not logged in');
          return;
        }

        if (response.ok) {
          const serverNotifications = await response.json();
          // Convert server notifications to client format
          const clientNotifications = serverNotifications.map((notif: any) => ({
            ...notif,
            timestamp: new Date(notif.timestamp)
          }));
          setNotifications(clientNotifications);
        } else {
          const errorText = await response.text();
          console.error('🔔 Failed to fetch notifications, status:', response.status, 'Error:', errorText);
        }
      } catch (error) {
        console.error('❌ Error fetching notifications:', error);
      }
    };

    // Initial fetch
    fetchNotifications();

    // Sync with server every 30 seconds to reduce resource usage
    const syncInterval = setInterval(fetchNotifications, 30000);

    return () => {
      clearInterval(syncInterval);
    };
  }, []);

  return (
    <BellNotificationContext.Provider value={{
      notifications,
      unreadCount,
      addNotification,
      markAsRead,
      markAllAsRead,
      removeNotification,
      clearAll
    }}>
      {children}
    </BellNotificationContext.Provider>
  );
}

export function useBellNotifications() {
  const context = useContext(BellNotificationContext);
  if (context === undefined) {
    throw new Error('useBellNotifications must be used within a BellNotificationProvider');
  }
  return context;
}

'use client';

import { createContext, useContext, useState, ReactNode } from 'react';

interface HistoricalModeContextType {
  // Current state
  isHistoricalMode: boolean;
  bypassHistoricalMode: boolean;
  currentPatient: string | null;
  loading: boolean;

  // Actions
  toggleHistoricalMode: () => void;
  setBypassHistoricalMode: (value: boolean) => void;
  setCurrentPatient: (patientId: string) => void;

  // Enhanced methods
  loadPatientSettings: (patientId: string) => Promise<void>;
  savePatientSettings: (patientId: string, bypass: boolean) => Promise<void>;
  getEffectiveMode: () => 'historical' | 'active' | 'bypassed';
}

const HistoricalModeContext = createContext<HistoricalModeContextType | undefined>(undefined);

export function HistoricalModeProvider({ children }: { children: ReactNode }) {
  const [isHistoricalMode, setIsHistoricalMode] = useState(false);
  const [bypassHistoricalMode, setBypassHistoricalMode] = useState(false);
  const [currentPatient, setCurrentPatient] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const toggleHistoricalMode = () => {
    setIsHistoricalMode(prev => !prev);
  };

  // Load patient-specific settings
  const loadPatientSettings = async (patientId: string) => {
    if (!patientId) return;

    setLoading(true);
    try {
      const { supabase } = await import('../lib/supabase');

      const { data, error } = await supabase
        .from('historical_mode_settings')
        .select('bypass_historical_mode')
        .eq('patient_id', patientId)
        .eq('clerk_user_id', 'system-migration-placeholder') // Match the placeholder
        .maybeSingle(); // Use maybeSingle instead of single to avoid 406

      if (error) {
        console.error('Error loading patient settings:', error);
        // Don't throw error for 406, just use default value
        if (error.code !== 'PGRST116') { // Not found error
          console.warn('Using default bypass setting due to error:', error.message);
        }
      }

      const bypassValue = data?.bypass_historical_mode ?? false;
      // Only update if value actually changed to prevent infinite loops
      setBypassHistoricalMode(prev => {
        if (prev !== bypassValue) {
          setCurrentPatient(patientId);
          return bypassValue;
        }
        return prev;
      });
    } catch (error) {
      console.error('Unexpected error loading patient settings:', error);
      setBypassHistoricalMode(false);
    } finally {
      setLoading(false);
    }
  };

  // Save patient-specific settings (global across all users)
  const savePatientSettings = async (patientId: string, bypass: boolean) => {
    if (!patientId) return;

    setLoading(true);
    try {
      const { supabase } = await import('../lib/supabase');

      // Use UPSERT to handle both insert and update in one atomic operation
      console.log('Attempting to save patient setting:', { patientId, bypass });

      const { error } = await supabase
        .from('historical_mode_settings')
        .upsert({
          patient_id: patientId,
          clerk_user_id: 'system-migration-placeholder', // Consistent placeholder
          bypass_historical_mode: bypass,
          updated_at: new Date().toISOString()
        }, {
          onConflict: 'patient_id,clerk_user_id' // Specify the unique constraint columns
        });

      console.log('Upsert result:', { error, patientId });

      if (error) {
        console.error('Error saving patient setting:', error);

        // If it's still a duplicate key error, try to clean up and retry
        if (error.code === '23505') {
          console.log('Duplicate key detected, attempting cleanup...');

          // Delete any existing duplicates and retry
          const { error: deleteError } = await supabase
            .from('historical_mode_settings')
            .delete()
            .eq('patient_id', patientId)
            .eq('clerk_user_id', 'system-migration-placeholder');

          if (deleteError) {
            console.error('Error cleaning up duplicates:', deleteError);
            throw deleteError;
          }

          // Retry the upsert after cleanup
          const { error: retryError } = await supabase
            .from('historical_mode_settings')
            .upsert({
              patient_id: patientId,
              clerk_user_id: 'system-migration-placeholder',
              bypass_historical_mode: bypass,
              updated_at: new Date().toISOString()
            }, {
              onConflict: 'patient_id,clerk_user_id'
            });

          if (retryError) {
            console.error('Error on retry:', retryError);
            throw retryError;
          }
        } else {
          throw error;
        }
      }

      // Only update if value actually changed to prevent infinite loops
      setBypassHistoricalMode(prev => {
        if (prev !== bypass) {
          return bypass;
        }
        return prev;
      });
    } catch (error) {
      console.error('Unexpected error saving patient settings:', error);
      throw error;
    } finally {
      setLoading(false);
    }
  };

  // Get effective mode for current patient
  const getEffectiveMode = (): 'historical' | 'active' | 'bypassed' => {
    if (!currentPatient) return 'active';
    if (!isHistoricalMode) return 'active';
    return bypassHistoricalMode ? 'bypassed' : 'historical';
  };

  return (
    <HistoricalModeContext.Provider value={{ 
      isHistoricalMode, 
      toggleHistoricalMode, 
      bypassHistoricalMode, 
      setBypassHistoricalMode, 
      setCurrentPatient, 
      currentPatient,
      loading,
      loadPatientSettings,
      savePatientSettings,
      getEffectiveMode
    }}>
      {children}
    </HistoricalModeContext.Provider>
  );
}

export function useHistoricalMode() {
  const context = useContext(HistoricalModeContext);
  if (context === undefined) {
    throw new Error('useHistoricalMode must be used within a HistoricalModeProvider');
  }
  return context;
}

