export function TutorialProvider({ children }: { children: ReactNode }) {
  const { user } = useUser();
  const { userRole } = useRoleBasedAccess();
  const [isActive, setIsActive] = useState(false);
  const [currentStep, setCurrentStep] = useState(0);
  const [steps, setSteps] = useState<TutorialStep[]>([]);

  useEffect(() => {
    if (user && userRole) {
      const hasSeenTutorial = localStorage.getItem(`tutorial_seen_${user.id}_${userRole}`);
      if (!hasSeenTutorial) {
        startTutorial();
      }
    }
  }, [user, userRole]);

  const startTutorial = () => {
    if (userRole && tutorials[userRole]) {
      setSteps(tutorials[userRole]);
      setCurrentStep(0);
      setIsActive(true);
    }
  };

  const nextStep = () => {
    if (currentStep < steps.length - 1) {
      setCurrentStep(currentStep + 1);
    } else {
      completeTutorial();
    }
  };

  const prevStep = () => {
    if (currentStep > 0) {
      setCurrentStep(currentStep - 1);
    }
  };

  const skipTutorial = () => {
    completeTutorial();
  };

  const completeTutorial = () => {
    setIsActive(false);
    if (user && userRole) {
      localStorage.setItem(`tutorial_seen_${user.id}_${userRole}`, 'true');
    }
  };

  return (
    <TutorialContext.Provider value={{
      isActive,
      currentStep,
      steps,
      startTutorial,
      nextStep,
      prevStep,
      skipTutorial,
      completeTutorial
    }}>
      {children}
    </TutorialContext.Provider>
  );
}

export function useTutorial() {
  const context = useContext(TutorialContext);
  if (context === undefined) {
    throw new Error('useTutorial must be used within a TutorialProvider');
  }
  return context;
}

// Potrace implementation for browser
// Source: https://github.com/kilobtye/potrace

export class Potrace {
  constructor() {
    this.defaults = {
      threshold: 128,
      turdSize: 2,
      color: '#000000',
      background: null,
      blackOnWhite: true,
      turnPolicy: 'minority',
      optTolerance: 0.2
    };
  }

  async traceCanvas(canvas, options = {}) {
    const params = { ...this.defaults, ...options };
    const imageData = canvas.getContext('2d').getImageData(0, 0, canvas.width, canvas.height);
    const bitmap = this.imageDataToBitmap(imageData, params.threshold);

    return this.trace(bitmap, params);
  }

  getSVG(paths, params = {}) {
    const { width, height, color, background } = { ...this.defaults, ...params };

    let svg = `<?xml version="1.0" standalone="no"?>\n`;
    svg += `<!DOCTYPE svg PUBLIC "-//W3C//DTD SVG 1.1//EN" "http://www.w3.org/Graphics/SVG/1.1/DTD/svg11.dtd">\n`;
    svg += `<svg width="${width}" height="${height}" version="1.1" xmlns="http://www.w3.org/2000/svg">\n`;

    if (background) {
      svg += `  <rect width="100%" height="100%" fill="${background}" />\n`;
    }

    svg += `  <path d="${paths}" fill="${color}" fill-rule="evenodd"/>\n`;
    svg += `</svg>`;

    return svg;
  }

  imageDataToBitmap(imageData, threshold) {
    const data = imageData.data;
    const width = imageData.width;
    const height = imageData.height;
    const bitmap = [];

    for (let y = 0; y < height; y++) {
      const row = [];
      for (let x = 0; x < width; x++) {
        const i = (y * width + x) * 4;
        const r = data[i];
        const g = data[i + 1];
        const b = data[i + 2];
        const gray = 0.2126 * r + 0.7152 * g + 0.0722 * b;
        row.push(gray < threshold ? 1 : 0);
      }
      bitmap.push(row);
    }

    return bitmap;
  }

  trace(bitmap, params) {
    // Simplified path generation
    // In a real implementation, this would use the Potrace algorithm
    // to trace the bitmap and generate SVG paths
    const width = bitmap[0].length;
    const height = bitmap.length;
    let path = '';

    // This is a simplified path generation
    // A real implementation would trace the actual shapes
    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        if (bitmap[y][x] === 1) {
          // Simple rectangle for each black pixel (simplified)
          if (path === '') {
            path = `M${x},${y}h1v1h-1z`;
          } else {
            path += ` M${x},${y}h1v1h-1z`;
          }
        }
      }
    }

    return path || 'M0,0z';
  }
}

