    console.log(`\n😎 AI Proxy Server listening on http://localhost:${PORT}`);
    console.log(`Target Model: gemini-2.5-pro`);
});

// shared-webp-converter.js
class WebPConverter {
    static async convertToWebP(file, options = {}) {
        const {
            quality = 0.85,
            maxWidth = null,
            lossless = false,
            stripMetadata = true
        } = options;

        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = async (event) => {
                try {
                    const img = new Image();
                    img.onload = () => {
                        const canvas = document.createElement('canvas');
                        const ctx = canvas.getContext('2d', { willReadFrequently: true });

                        // Calculate dimensions
                        let width = img.width;
                        let height = img.height;

                        if (maxWidth && width > maxWidth) {
                            const ratio = maxWidth / width;
                            width = maxWidth;
                            height = Math.round(height * ratio);
                        }

                        canvas.width = width;
                        canvas.height = height;

                        // Draw and process image
                        ctx.imageSmoothingEnabled = true;
                        ctx.imageSmoothingQuality = 'high';
                        ctx.drawImage(img, 0, 0, width, height);

                        // Convert to WebP
                        canvas.toBlob((blob) => {
                            if (!blob) {
                                reject(new Error('Conversion failed'));
                                return;
                            }

                            resolve({
                                blob: blob,
                                url: URL.createObjectURL(blob),
                                originalSize: file.size,
                                webpSize: blob.size,
                                width: width,
                                height: height
                            });
                        }, 'image/webp', quality);
                    };
                    img.onerror = () => reject(new Error('Failed to load image'));
                    img.src = event.target.result;
                } catch (error) {
                    reject(error);
                }
            };
            reader.onerror = () => reject(new Error('Failed to read file'));
            reader.readAsDataURL(file);
        });
    }

    static formatFileSize(bytes) {
        if (bytes === 0) return '0 Bytes';
        const k = 1024;
        const sizes = ['Bytes', 'KB', 'MB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
    }
}

'use client';

import { useEffect, useRef } from 'react';
import { useBellNotifications } from '../contexts/BellNotificationContext';

export function useNotificationListener() {
  const { notifications } = useBellNotifications();
  const lastNotificationCount = useRef(0);
  const processedNotifications = useRef<Set<string>>(new Set());

  useEffect(() => {
    // Check for new notifications
    const currentCount = notifications.length;

    if (currentCount > lastNotificationCount.current) {
      // We have new notifications
      const newNotifications = notifications.slice(0, currentCount - lastNotificationCount.current);

      newNotifications.forEach(notification => {
        // Only trigger browser notification for unread notifications we haven't processed yet
        if (!notification.read && !processedNotifications.current.has(notification.id)) {
          triggerBrowserNotification(notification);
          processedNotifications.current.add(notification.id);
        }
      });

      lastNotificationCount.current = currentCount;
    }
  }, [notifications]);

  // Clean up processed notifications periodically to prevent memory leaks
  useEffect(() => {
    const interval = setInterval(() => {
      // Remove old processed notification IDs (keep only last 50)
      const allIds = notifications.map(n => n.id);
      const recentIds = allIds.slice(0, 50);
      processedNotifications.current = new Set(
        Array.from(processedNotifications.current).filter(id => recentIds.includes(id))
      );
    }, 60000); // Clean up every minute

    return () => clearInterval(interval);
  }, [notifications]);
}

function triggerBrowserNotification(notification: any) {
  // Check if browser notifications are supported and permission is granted
  if ('Notification' in window && Notification.permission === 'granted') {
    // Extract event time from metadata if available
    let body = notification.message;
    if (notification.metadata?.eventTime || notification.metadata?.taskTime) {
      const eventTime = new Date(notification.metadata.eventTime || notification.metadata.taskTime);
      const formattedTime = eventTime.toLocaleDateString('es-HN', {
        day: '2-digit',
        month: '2-digit',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        timeZone: 'America/Tegucigalpa' // Explicitly set to Honduras timezone
      });

      // Add time information to the notification body
      body += ` | ${formattedTime}`;
    }

    console.log(`🔔 Triggering browser notification: ${notification.title}`);

    // Create notification that works in both mobile and desktop modes
    const browserNotification = new Notification(notification.title, {
      icon: '/Logo.svg', // Use the proper logo
      badge: '/Logo.svg', // Use the proper logo for badge
      tag: notification.type || 'general',
      requireInteraction: false, // Changed to false for better mobile experience
      body: body,
      data: notification.metadata,
    });

    // Play sound if available (disabled to prevent 404 errors)
    // try {
    //   const audio = new Audio('/notification-sound.mp3');
    //   audio.play().catch(() => {
    //     console.log('🔊 Audio play failed (this is normal in many browsers)');
    //   });
    // } catch (error) {
    //   console.log('🔊 Audio not available');
    // }

    // Handle notification click
    browserNotification.onclick = () => {
      console.log('🖱️ Browser notification clicked');
      browserNotification.close();

      // Focus the window if possible
      if (window.focus) {
        window.focus();
      }

      // Navigate to calendar if it's a calendar notification
      if (notification.type === 'calendar_event' || notification.type === 'calendar_task') {
        window.location.href = '/calendario';
      }
    };

    // Auto-close after 8 seconds
    setTimeout(() => {
      browserNotification.close();
    }, 8000);

    console.log(`✅ Browser notification triggered successfully: ${notification.title}`);
  } else {
    console.log('🔔 Browser notifications not available or permission not granted');

    // Request permission if it's 'default'
    if ('Notification' in window && Notification.permission === 'default') {
      console.log('🔔 Requesting browser notification permission...');
      Notification.requestPermission().then(permission => {
        if (permission === 'granted') {
          console.log('✅ Browser notification permission granted!');
          // Try again with the notification
          triggerBrowserNotification(notification);
        } else {
          console.log('❌ Browser notification permission denied');
        }
      });
    }
  }
}

'use client';

import { useState, useEffect } from 'react';
import { calculateProgress, extractMonthsFromDuration, calculateEstimatedAppointments, getProgressStatus, getProgressColor } from '@/utils/progressUtils';
import { orthodonticVersionService } from '@/services/orthodonticVersionService';

export interface UseProgressCalculationProps {
  patientId: string;
  duracionTratamiento?: string;
}

export interface ProgressData {
  completedAppointments: number;
  totalEstimatedAppointments: number;
  progressPercentage: number;
  estimatedDuration: number;
  elapsedMonths: number;
  status: string;
  color: string;
  loading: boolean;
  error: string | null;
}

export const useProgressCalculation = ({ 
  patientId, 
  duracionTratamiento 
}: UseProgressCalculationProps): ProgressData => {
  const [progressData, setProgressData] = useState<ProgressData>({
    completedAppointments: 0,
    totalEstimatedAppointments: 12,
    progressPercentage: 0,
    estimatedDuration: extractMonthsFromDuration(duracionTratamiento || '12 meses'),
    elapsedMonths: 0,
    status: 'No iniciado',
    color: 'bg-red-500',
    loading: true,
    error: null
  });

  useEffect(() => {
    const fetchProgressData = async () => {
      if (!patientId) {
        setProgressData(prev => ({ ...prev, loading: false }));
        return;
      }

      try {
        const versions = await orthodonticVersionService.getVersionsByPatientId(patientId);

        // Get the latest version by date (not the isCurrent flag)
        if (versions.length > 0) {
          const sortedVersions = [...versions].sort((a, b) => 
            new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
          );
          const latestVersion = sortedVersions[0];

          // Calculate progress based on duracionTratamiento
          const completedAppointments = latestVersion.completedAppointments || 0;
          const effectiveDuracion = latestVersion.duracionTratamiento || duracionTratamiento || '12 meses';
          const estimatedDuration = extractMonthsFromDuration(effectiveDuracion);

          // Recalculate progress percentage based on duration
          const calculatedProgress = calculateProgress(
            completedAppointments,
            estimatedDuration, // Use duration as total appointments
            effectiveDuracion
          );

          setProgressData({
            completedAppointments,
            totalEstimatedAppointments: calculatedProgress.totalEstimatedAppointments,
            progressPercentage: calculatedProgress.progressPercentage,
            estimatedDuration,
            elapsedMonths: 0, // TODO: Calculate from start date
            status: calculatedProgress.status,
            color: calculatedProgress.color,
            loading: false,
            error: null
          });
        } else {
          // No current version, use defaults
          const estimatedDuration = extractMonthsFromDuration(duracionTratamiento || '12 meses');
          const totalEstimatedAppointments = calculateEstimatedAppointments(duracionTratamiento || '12 meses');

          setProgressData({
            completedAppointments: 0,
            totalEstimatedAppointments,
            progressPercentage: 0,
            estimatedDuration,
            elapsedMonths: 0,
            status: 'No iniciado',
            color: 'bg-red-500',
            loading: false,
            error: null
          });
        }
      } catch (error) {
        console.error('Error fetching progress data:', error);
        setProgressData(prev => ({
          ...prev,
          loading: false,
          error: error instanceof Error ? error.message : 'Failed to load progress data'
        }));
      }
    };

    fetchProgressData();
  }, [patientId, duracionTratamiento]);

  return progressData;
};

import { useState, useEffect, useCallback } from 'react';
import { useUser } from '@clerk/nextjs';
import { UserPreferencesService, UserPreferences } from '../services/userPreferencesService';

interface UseUserPreferencesReturn {
  preferences: UserPreferences | null;
  loading: boolean;
  error: string | null;
  updatePagePreferences: (page: string, prefs: any) => Promise<void>;
  getPagePreferences: (page: string) => Promise<any>;
  updateGlobalPreferences: (prefs: any) => Promise<void>;
  getGlobalPreferences: () => Promise<any>;
  refreshPreferences: () => Promise<void>;
}

export function useUserPreferences(): UseUserPreferencesReturn {
  const { user, isLoaded } = useUser();
  const [preferences, setPreferences] = useState<UserPreferences | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Load user preferences
  const loadPreferences = useCallback(async () => {
    if (!user?.id) {
      setLoading(false);
      return;
    }

    try {
      setLoading(true);
      setError(null);
      const userPrefs = await UserPreferencesService.getUserPreferences(user.id);
      setPreferences(userPrefs);
    } catch (err) {
      console.error('Error loading user preferences:', err);
      setError('Failed to load preferences');
    } finally {
      setLoading(false);
    }
  }, [user?.id]);

  // Update page preferences
  const updatePagePreferences = useCallback(async (page: string, prefs: any) => {
    if (!user?.id) {
      throw new Error('User not authenticated');
    }

    try {
      const updatedPrefs = await UserPreferencesService.updatePagePreferences(
        user.id,
        page,
        prefs
      );
      setPreferences(updatedPrefs);
    } catch (err) {
      console.error('Error updating page preferences:', err);
      // Don't throw error, just log it to prevent UI breaking
      // For network errors, use optimistic update
      if (err instanceof TypeError && err.message?.includes('Failed to fetch')) {
        console.warn('Network error detected, using optimistic update for page preferences');
        setPreferences(current => {
          if (!current) return null;
          return {
            ...current,
            page_preferences: {
              ...current.page_preferences,
              [page]: {
                ...current.page_preferences?.[page] || {},
                ...prefs
              }
            }
          };
        });
      }
    }
  }, [user?.id]);

  // Get page preferences
  const getPagePreferences = useCallback(async (page: string) => {
    if (!user?.id) {
      return null;
    }

    try {
      return await UserPreferencesService.getPagePreferences(user.id, page);
    } catch (err) {
      console.error('Error getting page preferences:', err);
      return null;
    }
  }, [user?.id]);

  // Update global preferences
  const updateGlobalPreferences = useCallback(async (prefs: any) => {
    if (!user?.id) {
      throw new Error('User not authenticated');
    }

    try {
      const updatedPrefs = await UserPreferencesService.updateGlobalPreferences(
        user.id,
        prefs
      );
      setPreferences(updatedPrefs);
    } catch (err) {
      console.error('Error updating global preferences:', err);
      // Don't throw error, just log it to prevent UI breaking
    }
  }, [user?.id]);

  // Get global preferences
  const getGlobalPreferences = useCallback(async () => {
    if (!user?.id) {
      return null;
    }

    try {
      return await UserPreferencesService.getGlobalPreferences(user.id);
    } catch (err) {
      console.error('Error getting global preferences:', err);
      return null;
    }
  }, [user?.id]);

  // Refresh preferences
  const refreshPreferences = useCallback(async () => {
    await loadPreferences();
  }, [loadPreferences]);

  // Load preferences when user is loaded
  useEffect(() => {
    if (isLoaded) {
      loadPreferences();
    }
  }, [isLoaded, loadPreferences]);

  return {
    preferences,
    loading,
    error,
    updatePagePreferences,
    getPagePreferences,
    updateGlobalPreferences,
    getGlobalPreferences,
    refreshPreferences
  };
}

// Helper hook for specific page preferences
export function usePagePreferences(page: string) {
  const { preferences, updatePagePreferences, getPagePreferences, loading, error } = useUserPreferences();
  const [pagePrefs, setPagePrefs] = useState<any>(null);

  // Get page preferences
  useEffect(() => {
    const loadPagePrefs = async () => {
      if (preferences?.page_preferences?.[page]) {
        setPagePrefs(preferences.page_preferences[page]);
      } else {
        const prefs = await getPagePreferences(page);
        setPagePrefs(prefs);
      }
    };

    if (page) {
      loadPagePrefs();
    }
  }, [preferences, page, getPagePreferences]);

  // Update page preferences
  const updatePrefs = useCallback(async (newPrefs: any) => {
    await updatePagePreferences(page, newPrefs);
    setPagePrefs(prev => ({ ...prev, ...newPrefs }));
  }, [updatePagePreferences, page]);

  return {
    preferences: pagePrefs,
    updatePreferences: updatePrefs,
    loading,
    error
  };
}

// Helper hook for global preferences
export function useGlobalPreferences() {
  const { preferences, updateGlobalPreferences, getGlobalPreferences, loading, error } = useUserPreferences();
  const [globalPrefs, setGlobalPrefs] = useState<any>(null);

  // Get global preferences
  useEffect(() => {
    const loadGlobalPrefs = async () => {
      if (preferences?.global_preferences) {
        setGlobalPrefs(preferences.global_preferences);
      } else {
        const prefs = await getGlobalPreferences();
        setGlobalPrefs(prefs);
      }
    };

    loadGlobalPrefs();
  }, [preferences, getGlobalPreferences]);

  // Update global preferences
  const updatePrefs = useCallback(async (newPrefs: any) => {
    await updateGlobalPreferences(newPrefs);
    setGlobalPrefs(prev => ({ ...prev, ...newPrefs }));
  }, [updateGlobalPreferences]);

  return {
    preferences: globalPrefs,
    updatePreferences: updatePrefs,
    loading,
    error
  };
}

'use client';

import { useState, useEffect } from 'react';
import { OrthodonticVersion, sortVersionsByDate, getCurrentVersion, getNextVersionNumber } from '@/utils/versionUtils';
import { extractMonthsFromDuration } from '@/utils/progressUtils';
import { orthodonticVersionService } from '@/services/orthodonticVersionService';
import { SimpleTimezoneFix } from '@/services/simpleTimezoneFix';

export interface UseVersionManagementProps {
  patientId: string;
}

export interface VersionManagementData {
  versions: OrthodonticVersion[];
  currentVersion: OrthodonticVersion | null;
  selectedVersion: OrthodonticVersion | null;
  loading: boolean;
  error: string | null;
  actions: {
    loadVersions: () => Promise<void>;
    selectVersion: (version: OrthodonticVersion) => void;
    createNewVersion: (recordDate: Date, notes: string) => Promise<void>;
    updateCurrentVersion: (versionData: Partial<OrthodonticVersion>) => Promise<void>;
    makeVersionCurrent: (versionId: string) => Promise<void>;
    refreshVersions: () => Promise<void>;
  };
}

export const useVersionManagement = ({ patientId }: UseVersionManagementProps): VersionManagementData => {
  const [versions, setVersions] = useState<OrthodonticVersion[]>([]);
  const [selectedVersion, setSelectedVersion] = useState<OrthodonticVersion | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const loadVersions = async () => {
    if (!patientId) return;

    setLoading(true);
    setError(null);

    try {
      const fetchedVersions = await orthodonticVersionService.getVersionsByPatientId(patientId);
      const sortedVersions = sortVersionsByDate(fetchedVersions);
      setVersions(sortedVersions);

      // Auto-select current version
      const current = getCurrentVersion(sortedVersions);
      if (current && !selectedVersion) {
        setSelectedVersion(current);
      }
    } catch (err) {
      console.error('Error loading versions:', err);
      setError(err instanceof Error ? err.message : 'Failed to load versions');
    } finally {
      setLoading(false);
    }
  };

  const selectVersion = (version: OrthodonticVersion) => {
    setSelectedVersion(version);
  };

  const createNewVersion = async (recordDate: Date, notes: string) => {
    if (!patientId) return;

    setLoading(true);
    setError(null);

    try {
      // Get the latest version by date (not the isCurrent flag)
      const sortedVersions = sortVersionsByDate(versions);
      const latestVersion = sortedVersions[0];

      // Auto-increment completed appointments for new versions
      const currentCompleted = latestVersion?.completedAppointments || 0;
      const newCompleted = currentCompleted + 1;

      // Calculate progress based on actual treatment data
      const versionData = latestVersion ? {
        pacienteId: latestVersion.pacienteId || patientId,
        doctorId: latestVersion.doctorId,
        motivoConsultaOrtodoncia: latestVersion.motivoConsultaOrtodoncia,
        diagnosticoOrtodoncia: latestVersion.diagnosticoOrtodoncia,
        planTratamientoOrtodoncia: latestVersion.planTratamientoOrtodoncia,
        tipoMordida: latestVersion.tipoMordida,
        tipoAparato: latestVersion.tipoAparato,
        duracionTratamiento: latestVersion.duracionTratamiento,
        fechaInicioTratamiento: latestVersion.fechaInicioTratamiento,
        fechaFinTratamiento: latestVersion.fechaFinTratamiento,
        observacionesOrtodoncia: latestVersion.observacionesOrtodoncia,
        radiografiasRealizadas: latestVersion.radiografiasRealizadas,
        modelosEstudio: latestVersion.modelosEstudio,
        analisisCefalometrico: latestVersion.analisisCefalometrico,
        extraccionesRealizadas: latestVersion.extraccionesRealizadas,
        retenedorTipo: latestVersion.retenedorTipo,
        retenedorUso: latestVersion.retenedorUso,
        retenedorInferiorTipo: latestVersion.retenedorInferiorTipo,
        retenedorInferiorUso: latestVersion.retenedorInferiorUso,
        seguimientoPostTratamiento: latestVersion.seguimientoPostTratamiento,
        documentosOrtodoncia: latestVersion.documentosOrtodoncia,
        firmaDigitalOrtodoncia: latestVersion.firmaDigitalOrtodoncia,
        // Auto-increment completed appointments
        completedAppointments: newCompleted,
        totalEstimatedAppointments: latestVersion.totalEstimatedAppointments || 12
      } : {
        // First version - start with 1 completed appointment
        pacienteId: patientId,
        completedAppointments: 1,
        totalEstimatedAppointments: 12
      };

      const newVersion = await orthodonticVersionService.createVersion(
        patientId,
        {
          ...versionData,
          recordDate: SimpleTimezoneFix.toDateString(recordDate),
          notes
        },
        false // Don't make new versions current by default
      );

      // Refresh versions
      await loadVersions();
    } catch (err) {
      console.error('Error creating new version:', err);
      setError(err instanceof Error ? err.message : 'Failed to create new version');
    } finally {
      setLoading(false);
    }
  };

  const updateCurrentVersion = async (versionData: Partial<OrthodonticVersion>) => {
    if (!patientId) return;

    setLoading(true);
    setError(null);

    try {
      const currentVersions = await orthodonticVersionService.getVersionsByPatientId(patientId);
      const currentVersion = currentVersions.find(v => v.isCurrent);

      if (!currentVersion) {
        // No current version exists, create the first one
        console.log('No current version found, creating first version...');
        await orthodonticVersionService.createVersion(patientId, {
          ...versionData,
          progressPercentage: 0,
          completedAppointments: 0,
          totalEstimatedAppointments: 12
        }, true);
        return;
      }

      // Calculate progress based on actual treatment data (duration and completed appointments)
      const duracionTratamiento = versionData.duracionTratamiento || currentVersion.duracionTratamiento || '12 meses';
      const totalEstimatedAppointments = Math.max(extractMonthsFromDuration(duracionTratamiento), 4);
      const completedAppointments = versionData.completedAppointments !== undefined 
        ? versionData.completedAppointments 
        : currentVersion.completedAppointments || 0;

      // Calculate actual progress percentage
      const progressPercentage = totalEstimatedAppointments > 0 
        ? Math.min(Math.round((completedAppointments / totalEstimatedAppointments) * 100), 100)
        : 0;

      // Update existing current version with calculated progress
      await orthodonticVersionService.updateCurrentVersion(patientId, {
        ...currentVersion,
        ...versionData,
        progressPercentage,
        completedAppointments,
        totalEstimatedAppointments
      });
    } catch (err) {
      console.error('Error updating current version:', err);
      setError(err instanceof Error ? err.message : 'Failed to update current version');
    } finally {
      setLoading(false);
    }
  };

  const makeVersionCurrent = async (versionId: string) => {
    if (!patientId) return;

    setLoading(true);
    setError(null);

    try {
      await orthodonticVersionService.makeVersionCurrent(patientId, versionId);
      await loadVersions();
    } catch (err) {
      console.error('Error making version current:', err);
      setError(err instanceof Error ? err.message : 'Failed to make version current');
    } finally {
      setLoading(false);
    }
  };

  const refreshVersions = async () => {
    await loadVersions();
  };

  useEffect(() => {
    loadVersions();
  }, [patientId]);

  const currentVersion = getCurrentVersion(versions);

  return {
    versions,
    currentVersion,
    selectedVersion,
    loading,
    error,
    actions: {
      loadVersions,
      selectVersion,
      createNewVersion,
      updateCurrentVersion,
      makeVersionCurrent,
      refreshVersions
    }
  };
};

import { UserRole } from '@/types/ticket';

export const PERMISSIONS = {
  CLOSE_SYSTEM_TICKET: [UserRole.TECH_SUPPORT, UserRole.ADMIN],
  CLOSE_TICKET: [UserRole.ADMIN, UserRole.TECH_SUPPORT, UserRole.DOCTOR],
  CREATE_TICKET: [UserRole.STAFF, UserRole.DOCTOR, UserRole.ADMIN, UserRole.TECH_SUPPORT],
  ASSIGN_TASKS: [UserRole.DOCTOR, UserRole.ADMIN, UserRole.TECH_SUPPORT],
  DELETE_TICKET: [UserRole.ADMIN, UserRole.TECH_SUPPORT],
  VIEW_ALL_DEPARTMENTS: [UserRole.ADMIN, UserRole.TECH_SUPPORT, UserRole.DOCTOR],
  CREATE_PATIENT_CASE: [UserRole.DOCTOR, UserRole.ADMIN, UserRole.TECH_SUPPORT],
  VIEW_SYSTEM_LOGS: [UserRole.ADMIN, UserRole.TECH_SUPPORT],
  MANAGE_USERS: [UserRole.ADMIN],
  MANAGE_ROLES: [UserRole.ADMIN],
  ACCESS_TECH_SUPPORT: [UserRole.TECH_SUPPORT, UserRole.ADMIN],
  ACCESS_FINANCIAL_REPORTS: [UserRole.ADMIN],
  MODIFY_SYSTEM_SETTINGS: [UserRole.ADMIN],
} as const;

export type Permission = keyof typeof PERMISSIONS;

export function checkPermission(userRole: UserRole, permission: Permission): boolean {
  return PERMISSIONS[permission].includes(userRole as any);
}

export function requirePermission(userRole: UserRole, permission: Permission): void {
  if (!checkPermission(userRole, permission)) {
    throw new Error(`Access denied: ${permission} requires one of these roles: ${PERMISSIONS[permission].join(', ')}`);
  }
}

export function getPermissionsForRole(userRole: UserRole): Permission[] {
  return Object.keys(PERMISSIONS).filter(permission => 
    checkPermission(userRole, permission as Permission)
  ) as Permission[];
}

import { Workbox } from 'workbox-window';

export const registerServiceWorker = async () => {
  if (typeof window !== 'undefined' && 'serviceWorker' in navigator) {
    try {
      const wb = new Workbox('/sw.js');

      // Listen for waiting service worker
      wb.addEventListener('waiting', (event) => {
        // Show update prompt to user
        if (confirm('New version available! Reload to update?')) {
          wb.messageSkipWaiting();
        }
      });

      // Listen for controlling service worker
      wb.addEventListener('controlling', () => {
        // Reload the page to get the new version
        window.location.reload();
      });

      // Register the service worker
      await wb.register();
      console.log('✅ Service Worker registered successfully');

      return wb;
    } catch (error) {
      console.error('❌ Service Worker registration failed:', error);
      return null;
    }
  }
  return null;
};

export const unregisterServiceWorker = async () => {
  if (typeof window !== 'undefined' && 'serviceWorker' in navigator) {
    try {
      const registration = await navigator.serviceWorker.ready;
      await registration.unregister();
      console.log('✅ Service Worker unregistered successfully');
    } catch (error) {
      console.error('❌ Service Worker unregistration failed:', error);
    }
  }
};

export const checkServiceWorkerUpdate = async () => {
  if (typeof window !== 'undefined' && 'serviceWorker' in navigator) {
    try {
      const registration = await navigator.serviceWorker.ready;
      await registration.update();
      console.log('🔄 Service Worker update checked');
    } catch (error) {
      console.error('❌ Service Worker update check failed:', error);
    }
  }
};

import { clerkMiddleware, createRouteMatcher } from '@clerk/nextjs/server';
import { NextResponse } from 'next/server';

const isPublicRoute = createRouteMatcher([
  '/',
  '/sign-in(.*)',
  '/api/(.*)',
  '/api/terminal/(.*)',
  '/api/tickets/(.*)',  // Add tickets API routes
  '/tech-support/terminal',
  '/tech-support/(.*)',
  '/capacitor-demo',  // Add capacitor demo as public route
]);

// Server-side access control logic (copied from client hook)
function canAccessRouteServer(userRole: string, pathname: string): boolean {
  // Define route permissions
  const routePermissions: Record<string, string[]> = {
    '/dashboard': ['admin', 'doctor', 'assistant'],
    '/pacientes': ['admin', 'doctor', 'assistant'],
    '/calendario': ['admin', 'doctor', 'assistant'],
    '/odontogram': ['admin', 'doctor', 'assistant'],
    '/odontogram-test': ['admin', 'doctor', 'assistant'],
    '/tratamientos': ['admin', 'doctor', 'assistant'],
    '/tratamientos-completados': ['admin', 'doctor', 'assistant'],
    '/presupuestos': ['admin', 'doctor', 'assistant'],
    '/consentimientos': ['admin', 'doctor', 'assistant'],
    '/estudio-periodontal': ['admin', 'doctor', 'assistant'],
    '/patient-form': ['admin', 'doctor', 'assistant'],
    '/menu-navegacion': ['admin', 'doctor', 'assistant'],
    '/reports': ['admin', 'doctor', 'assistant'], // Allow doctors to access reports for testing
    '/doctores': ['admin'],
    '/tech-support': ['admin'],
  };

  console.log('🔍 ROUTE PERMISSIONS CHECK:', {
    pathname,
    userRole,
    allowedRoles: routePermissions[pathname],
    routeExists: !!routePermissions[pathname]
  });

  // Check if route exists in permissions
  const allowedRoles = routePermissions[pathname];

  // If route not found, allow access (default behavior)
  if (!allowedRoles) {
    console.log('✅ ROUTE NOT FOUND - ALLOWING ACCESS');
    return true;
  }

  // Check if user role is allowed
  const hasAccess = allowedRoles.includes(userRole);
  console.log('🔍 ACCESS CHECK RESULT:', {
    pathname,
    userRole,
    allowedRoles,
    hasAccess
  });

  return hasAccess;
}

export default clerkMiddleware(async (auth, req) => {
  if (!isPublicRoute(req)) {
    // Get auth data for each request
    const { userId } = await auth();

    if (!userId) {
      const { redirectToSignIn } = await auth();
      return redirectToSignIn();
    }

    // Get user role from metadata - check multiple locations
    const { sessionClaims, userId: recheckedUserId } = await auth();

    // Try different metadata locations from session claims
    let userRole = 'staff'; // default
    if ((sessionClaims as any)?.public_metadata?.role) {
      userRole = (sessionClaims as any).public_metadata.role;
    } else if ((sessionClaims as any)?.metadata?.role) {
      userRole = (sessionClaims as any).metadata.role;
    } else if ((sessionClaims as any)?.role) {
      userRole = (sessionClaims as any).role as string;
    }

    // Special case for known tech support user
    if (recheckedUserId === 'user_3A1mYfR054eV3tqtellpfMKZ7f6') {
      userRole = 'tech_support';
    }

    // DEBUG: Log user role and access attempt
    console.log('🔍 MIDDLEWARE DEBUG:', {
      userId: recheckedUserId,
      pathname: req.nextUrl.pathname,
      detectedRole: userRole,
      sessionClaims: sessionClaims,
      publicMetadata: sessionClaims?.public_metadata,
      metadata: sessionClaims?.metadata
    });

    // MULTIPLE FALLBACKS FOR TECH SUPPORT ACCESS
    if (userRole === 'tech_support' || 
        userRole === 'tech-support' || 
        req.nextUrl.pathname.startsWith('/tech-support/') ||
        recheckedUserId === 'user_3A1mYfR054eV3tqtellpfMKZ7f6') { // Specific tech support user

      // If tech support user is trying to access general dashboard, redirect to tech support dashboard
      if (req.nextUrl.pathname === '/dashboard' || req.nextUrl.pathname === '/') {
        console.log('🔄 REDIRECTING TECH SUPPORT TO TECH DASHBOARD');
        return NextResponse.redirect(new URL('/tech-support/dashboard', req.url));
      }

      return NextResponse.next();
    }

    // TEMPORARY: Allow basic access for common routes while metadata issue is fixed
    // Check if any of the allowed routes match
    const allowedRoutes = [
      '/dashboard',
      '/pacientes',
      '/doctores',
      '/calendario',
      '/patient-form',
      '/consentimientos',
      '/odontogram',
      '/estudio-periodontal',
      '/menu-navegacion',
      '/tratamientos',
      '/presupuestos',
      '/tickets',
      '/xray-viewer',
      '/historia-clinica-ortodoncia',
      '/tratamientos-completados'
    ];

    // Check for exact match or starts with
    const isAllowedRoute = allowedRoutes.some(route => 
      req.nextUrl.pathname === route || req.nextUrl.pathname.startsWith(route)
    );

    if (isAllowedRoute) {
      console.log('✅ TEMPORARY ACCESS ALLOWED:', { pathname: req.nextUrl.pathname, userRole });
      return NextResponse.next();
    }

    // Reports page - restricted to doctors, admins, and tech-support only
    if (req.nextUrl.pathname === '/reports' || req.nextUrl.pathname === '/reportes') {
      // TEMPORARY: Allow all authenticated users to access reports for testing
      return NextResponse.next();

      if (userRole === 'doctor' || userRole === 'admin' || userRole === 'tech_support') {
        return NextResponse.next();
      } else {
        return new Response('Access Denied', { status: 403 });
      }
    }

    // EMERGENCY BYPASS: Allow tech-support/users access for tech support user while metadata is broken
    if (recheckedUserId === 'user_3A1mYfR054eV3tqtellpfMKZ7f6' && 
        req.nextUrl.pathname === '/tech-support/users') {
      return NextResponse.next();
    }

    // TEMPORARY: Allow tech-support/users for component-level access control
    if (req.nextUrl.pathname === '/tech-support/users') {
      return NextResponse.next();
    }

    // TESTING: Allow odontogram-test for all roles (testing page)
    if (req.nextUrl.pathname.startsWith('/odontogram-test')) {
      return NextResponse.next();
    }

    // Check route access using server-side function
    const hasAccess = canAccessRouteServer(userRole, req.nextUrl.pathname);
    console.log('🔍 ACCESS CONTROL DEBUG:', {
      userRole,
      pathname: req.nextUrl.pathname,
      hasAccess,
      routePermissions: {
        '/patient-form': ['admin', 'doctor', 'assistant'],
        '/dashboard': ['admin', 'doctor', 'assistant'],
        '/pacientes': ['admin', 'doctor', 'assistant'],
        '/calendario': ['admin', 'doctor', 'assistant']
      }
    });

    if (!hasAccess) {
      console.log('🚫 ACCESS DENIED for:', { userRole, pathname: req.nextUrl.pathname });
      return new Response('Access Denied', { status: 403 });
    } else {
      console.log('✅ ACCESS GRANTED for:', { userRole, pathname: req.nextUrl.pathname });
      return NextResponse.next();
    }
  }
});

