      }
      if (filter?.priority) {
        query = query.eq('priority', filter.priority);
      }
      if (filter?.date_range) {
        query = query
          .gte('start_date', filter.date_range.start)
          .lte('end_date', filter.date_range.end);
      }

      const { data, error } = await query
        .order('start_date', { ascending: true });

      if (error) {
        throw error;
      }

      return data || [];
    } catch (error) {
      throw error;
    }
  }

