  // Schedule mobile notification for calendar event
  static async scheduleEventNotification(event: CalendarEventWithPatient, reminderMinutes: number = 60): Promise<boolean> {
    try {
      const notificationService = CapacitorNotificationService.getInstance();

      // Calculate reminder time
      const eventDate = new Date(event.start_date);
      const reminderDate = new Date(eventDate.getTime() - reminderMinutes * 60 * 1000);

      // Only schedule if reminder date is in the future
      if (reminderDate > new Date()) {
        const eventNotification = {
          id: `calendar-event-${event.id}`,
          title: 'Evento de Calendario - Diamond Link',
          body: `${event.title}${event.patient?.nombre_completo ? ` con ${event.patient.nombre_completo}` : ''} en ${reminderMinutes} minutos`,
          scheduledDate: reminderDate,
          patientId: event.patient_id,
          appointmentId: `calendar-${event.id}`
        };

        const scheduled = await notificationService.scheduleAppointmentReminder(eventNotification);

        if (scheduled) {
          console.log('✅ Calendar event notification scheduled:', event.title);

          // Also create a database reminder record
          await this.createReminder({
            event_id: event.id,
            reminder_time: reminderDate.toISOString(),
            sent: false
          });
        }

        return scheduled;
      } else {
        console.log('⚠️ Event date is too soon to schedule notification');
        return false;
      }
    } catch (error) {
      console.error('❌ Failed to schedule calendar event notification:', error);
      return false;
    }
  }

  // Cancel calendar event notification
  static async cancelEventNotification(eventId: string): Promise<boolean> {
    try {
      const notificationService = CapacitorNotificationService.getInstance();
      const cancelled = await notificationService.cancelNotification(`calendar-event-${eventId}`);

      if (cancelled) {
        console.log('✅ Calendar event notification cancelled:', eventId);

        // Mark database reminders as sent/cancelled
        await supabase
          .from('calendar_reminders')
          .update({ sent: true })
          .eq('event_id', eventId)
          .eq('reminder_type', 'mobile_notification');
      }

      return cancelled;
    } catch (error) {
      console.error('❌ Failed to cancel calendar event notification:', error);
      return false;
    }
  }

  // Schedule multiple notifications for an event (e.g., 1 day before, 1 hour before)
  static async scheduleMultipleEventNotifications(event: CalendarEventWithPatient, reminderTimes: number[] = [1440, 60, 15]): Promise<boolean[]> {
    const results: boolean[] = [];

    for (const minutes of reminderTimes) {
      const scheduled = await this.scheduleEventNotification(event, minutes);
      results.push(scheduled);
    }

    console.log(`📅 Scheduled ${results.filter(r => r).length}/${results.length} notifications for event: ${event.title}`);
    return results;
  }

  // Send immediate notification for event changes
  static async sendEventChangeNotification(event: CalendarEventWithPatient, changeType: 'created' | 'updated' | 'cancelled'): Promise<void> {
    try {
      const notificationService = CapacitorNotificationService.getInstance();

      const changeMessages = {
        created: 'Nuevo evento creado',
        updated: 'Evento actualizado',
        cancelled: 'Evento cancelado'
      };

      const notification = {
        id: `event-change-${event.id}-${Date.now()}`,
        title: `${changeMessages[changeType]} - Diamond Link`,
        body: `${event.title}${event.patient?.nombre_completo ? ` - ${event.patient.nombre_completo}` : ''}`,
        icon: '/Logo.svg',
        tag: `event-change-${event.id}`,
        data: {
          eventId: event.id,
          patientId: event.patient_id,
          changeType,
          url: event.patient_id ? `/menu-navegacion?id=${event.patient_id}` : '/calendar'
        }
      };

      // Send immediate notification
      await notificationService.sendLocalNotification(notification);

      console.log(`📱 Event ${changeType} notification sent:`, event.title);
    } catch (error) {
      console.error('❌ Failed to send event change notification:', error);
    }
  }
}

'use client';

import React, { useEffect, useRef, useState } from 'react';
import { LocalNotifications } from '@capacitor/local-notifications';
import { PushNotifications } from '@capacitor/push-notifications';
import { AppLauncher } from '@capacitor/app-launcher';
import { Capacitor } from '@capacitor/core';
import MobileNotificationService, { PushNotification } from './mobileNotificationService';

export interface AppointmentNotification {
  id: string;
  title: string;
  body: string;
  scheduledDate: Date;
  patientId?: string;
  doctorId?: string;
  appointmentId?: string;
}

export class CapacitorNotificationService {
  private static instance: CapacitorNotificationService;
  private webService: MobileNotificationService;

  private constructor() {
    this.webService = MobileNotificationService.getInstance();
  }

  static getInstance(): CapacitorNotificationService {
    if (!CapacitorNotificationService.instance) {
      CapacitorNotificationService.instance = new CapacitorNotificationService();
    }
    return CapacitorNotificationService.instance;
  }

  // Check if running on native platform
  isNative(): boolean {
    try {
      return Capacitor.isNativePlatform();
    } catch (error) {
      console.warn('⚠️ Capacitor not available, assuming web platform:', error);
      return false;
    }
  }

  // Request notification permissions (Capacitor + Web fallback)
  async requestPermissions(): Promise<{ granted: boolean; platform: string }> {
    if (this.isNative()) {
      try {
        // Request local notification permissions
        const localPermission = await LocalNotifications.requestPermissions();

        // Request push notification permissions
        const pushPermission = await PushNotifications.requestPermissions();

        console.log('📱 Capacitor permissions:', { localPermission, pushPermission });

        return {
          granted: (localPermission as any).granted === 'granted' && (pushPermission as any).granted === 'granted',
          platform: 'capacitor'
        };
      } catch (error) {
        console.error('❌ Capacitor permission request failed:', error);
        // Fallback to web permissions
        const webPermission = await this.webService.requestPermission();
        return {
          granted: webPermission.granted,
          platform: 'web'
        };
      }
    } else {
      // Web permissions
      const webPermission = await this.webService.requestPermission();
      return {
        granted: webPermission.granted,
        platform: 'web'
      };
    }
  }

  // Schedule appointment reminder
  async scheduleAppointmentReminder(appointment: AppointmentNotification): Promise<boolean> {
    try {
      if (this.isNative()) {
        // Use Capacitor local notifications
        await LocalNotifications.schedule({
          notifications: [{
            id: parseInt(appointment.id),
            title: appointment.title,
            body: appointment.body,
            schedule: { at: appointment.scheduledDate },
            sound: 'default',
            smallIcon: 'notification_icon',
            largeIcon: 'notification_icon_large',
            iconColor: '#14b8a6',
            extra: {
              patientId: appointment.patientId,
              doctorId: appointment.doctorId,
              appointmentId: appointment.appointmentId,
              type: 'appointment_reminder'
            }
          }]
        });

        console.log('📱 Appointment reminder scheduled (Capacitor):', appointment);
        return true;
      } else {
        // Web fallback - schedule with browser notification
        const delay = appointment.scheduledDate.getTime() - Date.now();

        if (delay > 0) {
          setTimeout(() => {
            this.webService.showLocalNotification({
              id: appointment.id,
              title: appointment.title,
              body: appointment.body,
              icon: '/Logo.svg',
              tag: `appointment-${appointment.id}`,
              data: {
                patientId: appointment.patientId,
                appointmentId: appointment.appointmentId,
                url: appointment.patientId ? `/menu-navegacion?id=${appointment.patientId}` : undefined
              }
            });
          }, delay);

          console.log('🌐 Appointment reminder scheduled (Web):', appointment);
          return true;
        }
      }
    } catch (error) {
      console.error('❌ Failed to schedule appointment reminder:', error);
      return false;
    }

    return false;
  }

  // Register for push notifications
  async registerForPushNotifications(): Promise<string | null> {
    try {
      if (this.isNative()) {
        await PushNotifications.register();

        return new Promise((resolve) => {
          PushNotifications.addListener('registration', (token) => {
            console.log('📱 Push registration success:', token.value);
            resolve(token.value);

            // Send token to backend
            this.sendPushTokenToBackend(token.value);
          });

          PushNotifications.addListener('registrationError', (error) => {
            console.error('❌ Push registration error:', error);
            resolve(null);
          });
        });
      } else {
        console.log('🌐 Push notifications not supported on web');
        return null;
      }
    } catch (error) {
      console.error('❌ Failed to register for push notifications:', error);
      return null;
    }
  }

  // Handle incoming push notifications
  async setupPushNotificationHandlers(): Promise<void> {
    if (!this.isNative()) return;

    try {
      // Handle received push notifications
      PushNotifications.addListener('pushNotificationReceived', (notification) => {
        console.log('📱 Push notification received:', notification);

        // Show local notification
        this.webService.showLocalNotification({
          id: notification.id?.toString() || Date.now().toString(),
          title: notification.title || 'Diamond Link',
          body: notification.body || 'Tiene una nueva notificación',
          icon: '/Logo.svg',
          data: notification.data
        });
      });

      // Handle push notification clicks
      PushNotifications.addListener('pushNotificationActionPerformed', (notification) => {
        console.log('📱 Push notification clicked:', notification);

        const data = notification.notification.data;
        if (data?.patientId) {
          this.openPatientRecord(data.patientId);
        } else if (data?.appointmentId) {
          this.openAppointment(data.appointmentId);
        }
      });

      console.log('✅ Push notification handlers setup complete');
    } catch (error) {
      console.error('❌ Failed to setup push notification handlers:', error);
    }
  }

  // Open patient record via deep link
  async openPatientRecord(patientId: string): Promise<void> {
    try {
      if (this.isNative()) {
        const deepLink = `diamondlink://patient/${patientId}`;
        await AppLauncher.openUrl({ url: deepLink });
        console.log('📱 Opened patient record (Capacitor):', patientId);
      } else {
        // Web navigation
        window.location.href = `/menu-navegacion?id=${patientId}`;
        console.log('🌐 Opened patient record (Web):', patientId);
      }
    } catch (error) {
      console.error('❌ Failed to open patient record:', error);
    }
  }

  // Open appointment via deep link
  async openAppointment(appointmentId: string): Promise<void> {
    try {
      if (this.isNative()) {
        const deepLink = `diamondlink://appointment/${appointmentId}`;
        await AppLauncher.openUrl({ url: deepLink });
        console.log('📱 Opened appointment (Capacitor):', appointmentId);
      } else {
        // Web navigation
        window.location.href = `/appointments?id=${appointmentId}`;
        console.log('🌐 Opened appointment (Web):', appointmentId);
      }
    } catch (error) {
      console.error('❌ Failed to open appointment:', error);
    }
  }

  // Cancel scheduled notification
  async cancelNotification(notificationId: string): Promise<boolean> {
    try {
      if (this.isNative()) {
        await LocalNotifications.cancel({
          notifications: [{ id: parseInt(notificationId) }]
        });
        console.log('📱 Notification cancelled (Capacitor):', notificationId);
        return true;
      } else {
        // Web notifications can't be cancelled once scheduled with setTimeout
        console.log('🌐 Web notification cancellation not supported');
        return false;
      }
    } catch (error) {
      console.error('❌ Failed to cancel notification:', error);
      return false;
    }
  }

  // Get scheduled notifications
  async getScheduledNotifications(): Promise<any[]> {
    try {
      if (this.isNative()) {
        const pending = await LocalNotifications.getPending();
        console.log('📱 Scheduled notifications:', pending);
        return pending.notifications;
      } else {
        console.log('🌐 Web scheduled notifications not trackable');
        return [];
      }
    } catch (error) {
      console.error('❌ Failed to get scheduled notifications:', error);
      return [];
    }
  }

  // Send push token to backend
  private async sendPushTokenToBackend(token: string): Promise<void> {
    try {
      // This would integrate with your existing user management system
      console.log('📤 Sending push token to backend:', token);

      // Example implementation:
