        .from('dental_images')
        .insert(image)
        .select()
        .single();

      if (error) throw error;
      return data;

    } catch (error) {
      console.error('Error creating image record:', error);
      throw error;
    }
  }

  // Create annotation
  async createAnnotation(annotation: Partial<DentalAnnotation>): Promise<DentalAnnotation> {
    try {
      const { data, error } = await supabase
        .from('dental_annotations')
        .insert(annotation)
        .select()
        .single();

      if (error) throw error;
      return data;

    } catch (error) {
      console.error('Error creating annotation:', error);
      throw error;
    }
  }

  // Create report
  async createReport(report: Partial<DentalReport>): Promise<DentalReport> {
    try {
      const { data, error } = await supabase
        .from('dental_reports')
        .insert(report)
        .select()
        .single();

      if (error) throw error;
      return data;

    } catch (error) {
      console.error('Error creating report:', error);
      throw error;
    }
  }

  // Delete image
  async deleteImage(imageId: string): Promise<void> {
    try {
      // Get image info first
      const { data: imageData } = await supabase
        .from('dental_images')
        .select('image_url')
        .eq('id', imageId)
        .single();

      if (imageData?.image_url) {
        // Extract file path from URL
        const urlParts = imageData.image_url.split('/');
        const filePath = urlParts[urlParts.length - 2] + '/' + urlParts[urlParts.length - 1];

        // Delete from storage
        await supabase.storage
          .from('diamond_xrays')
          .remove([filePath]);
      }

      // Delete record
      const { error } = await supabase
        .from('dental_images')
        .delete()
        .eq('id', imageId);

      if (error) throw error;

    } catch (error) {
      console.error('Error deleting image:', error);
      throw error;
    }
  }

  // Get public URL for image
  getImagePublicUrl(imagePath: string): string {
    const { data } = supabase.storage
      .from('diamond_xrays')
      .getPublicUrl(imagePath);

    return data.publicUrl;
  }
}

