import { CalendarInviteesService } from './calendarInviteesService';
import { CalendarEventWithPatient } from '../types/calendar';
import { CalendarTaskWithPatient } from '../types/calendarTasks';

export class InviteeNotificationService {
  // Send notifications to all invitees of an event
  static async notifyEventInvitees(
    event: CalendarEventWithPatient, 
    type: 'created' | 'updated' | 'cancelled' | 'reminder'
  ) {
    try {
      // Get all invitees for this event
      const invitees = await CalendarInviteesService.getInviteesForItem('event', event.id);

      // Create notification data
      const notificationData = {
        type: 'calendar_event',
        title: this.getEventNotificationTitle(event, type),
        message: this.getEventNotificationMessage(event, type),
        metadata: {
          eventId: event.id,
          eventTitle: event.title,
          eventTime: new Date(event.start_date),
          patientName: event.patient?.nombre_completo,
          patientId: event.patient?.paciente_id,
          notificationType: type
        }
      };

      // Send notification to each invitee (send to all invitees, not just accepted)
      for (const invitee of invitees) {
        await this.sendNotificationToUser(invitee.user_id, notificationData);
      }
    } catch (error) {
      console.error('❌ Error notifying event invitees:', error);
    }
  }

  // Send notifications to all invitees of a task
  static async notifyTaskInvitees(
    task: CalendarTaskWithPatient, 
    type: 'created' | 'updated' | 'cancelled' | 'reminder'
  ) {
    try {
      // Get all invitees for this task
      const invitees = await CalendarInviteesService.getInviteesForItem('task', task.id);

      // Create notification data
      const notificationData = {
        type: 'calendar_task',
        title: this.getTaskNotificationTitle(task, type),
        message: this.getTaskNotificationMessage(task, type),
        metadata: {
          taskId: task.id,
          taskTitle: task.title,
          taskTime: task.due_date ? new Date(task.due_date) : null,
          patientName: task.patient?.nombre_completo,
          patientId: task.patient?.paciente_id,
          notificationType: type
        }
      };

      // Send notification to each invitee (send to all invitees, not just accepted)
      for (const invitee of invitees) {
        await this.sendNotificationToUser(invitee.user_id, notificationData);
      }
    } catch (error) {
      console.error('❌ Error notifying task invitees:', error);
    }
  }

  // Send notification to a specific user (bypassing current user authentication)
  private static async sendNotificationToUser(userId: string, notificationData: any) {
    try {
      // Use service role to send notification to any user
      const response = await fetch('/api/notifications/send-to-user', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          userId,
          notification: notificationData
        }),
      });

      if (!response.ok) {
        const errorText = await response.text();
        console.error(`❌ Error sending notification to user ${userId}:`, errorText);
      }
    } catch (error) {
      console.error(`❌ Error sending notification to user ${userId}:`, error);
    }
  }

  private static getEventNotificationTitle(event: CalendarEventWithPatient, type: 'created' | 'updated' | 'cancelled' | 'reminder'): string {
    const patientName = event.patient?.nombre_completo || 'Sin paciente';

    switch (type) {
      case 'created':
        return `Nueva cita: ${event.title}`;
      case 'updated':
        return `Cita actualizada: ${event.title}`;
      case 'cancelled':
        return `Cita cancelada: ${event.title}`;
      case 'reminder':
        return `Recordatorio: ${event.title}`;
      default:
        return `Cita: ${event.title}`;
    }
  }

  private static getEventNotificationMessage(event: CalendarEventWithPatient, type: 'created' | 'updated' | 'cancelled' | 'reminder'): string {
    const eventDate = new Date(event.start_date);
    const formattedDate = eventDate.toLocaleDateString('es-HN', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      timeZone: 'America/Tegucigalpa' // Explicitly set to Honduras timezone
    });

    const patientName = event.patient?.nombre_completo || 'Sin paciente';

    switch (type) {
      case 'created':
        return `Cita agendada para ${patientName} el ${formattedDate}`;
      case 'updated':
        return `Cita modificada para ${patientName} el ${formattedDate}`;
      case 'cancelled':
        return `Cita cancelada para ${patientName} el ${formattedDate}`;
      case 'reminder':
        return `Recordatorio: Tu cita "${event.title}"${patientName !== 'Sin paciente' ? ` con ${patientName}` : ''} es ${formattedDate}`;
      default:
        return `Cita para ${patientName} el ${formattedDate}`;
    }
  }

  private static getTaskNotificationTitle(task: CalendarTaskWithPatient, type: 'created' | 'updated' | 'cancelled' | 'reminder'): string {
    const patientName = task.patient?.nombre_completo || 'Sin paciente';

    switch (type) {
      case 'created':
        return `Nueva tarea: ${task.title}`;
      case 'updated':
        return `Tarea actualizada: ${task.title}`;
      case 'cancelled':
        return `Tarea cancelada: ${task.title}`;
      case 'reminder':
        return `Recordatorio: ${task.title}`;
      default:
        return `Tarea: ${task.title}`;
    }
  }

  private static getTaskNotificationMessage(task: CalendarTaskWithPatient, type: 'created' | 'updated' | 'cancelled' | 'reminder'): string {
    if (!task.due_date) {
      return `Tarea "${task.title}"${task.patient?.nombre_completo ? ` para ${task.patient.nombre_completo}` : ''} sin fecha límite`;
    }

    const taskDate = new Date(task.due_date);
    const formattedDate = taskDate.toLocaleDateString('es-HN', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      timeZone: 'America/Tegucigalpa' // Explicitly set to Honduras timezone
    });

    const patientName = task.patient?.nombre_completo || 'Sin paciente';

    switch (type) {
      case 'created':
        return `Tarea creada para ${patientName} con fecha límite ${formattedDate}`;
      case 'updated':
        return `Tarea modificada para ${patientName} con fecha límite ${formattedDate}`;
      case 'cancelled':
        return `Tarea cancelada para ${patientName}`;
      case 'reminder':
        return `Recordatorio: Tu tarea "${task.title}"${patientName !== 'Sin paciente' ? ` para ${patientName}` : ''} vence ${formattedDate}`;
      default:
        return `Tarea para ${patientName} con fecha límite ${formattedDate}`;
    }
  }
}

'use client';

import { useEffect, useRef, useState } from 'react';
import { useDeviceInfo } from '@/hooks/useDeviceInfo';

export interface MobileAnalyticsEvent {
  event: string;
  properties?: Record<string, any>;
  timestamp: number;
  userId?: string;
  sessionId: string;
  deviceInfo: {
    isMobile: boolean;
    isTablet: boolean;
    isDesktop: boolean;
    isIOS: boolean;
    isAndroid: boolean;
    screenWidth: number;
    screenHeight: number;
    orientation: string;
  };
  page: {
    url: string;
    title: string;
    referrer?: string;
  };
  performance?: {
    loadTime?: number;
    domContentLoaded?: number;
    firstContentfulPaint?: number;
  };
}

export interface MobileAnalyticsConfig {
  apiKey?: string;
  endpoint?: string;
  debug?: boolean;
  trackPageViews?: boolean;
  trackEvents?: boolean;
  trackPerformance?: boolean;
  sampleRate?: number;
}

class MobileAnalyticsService {
  private static instance: MobileAnalyticsService;
  private config: MobileAnalyticsConfig;
  private sessionId: string;
  private userId?: string;
  private eventQueue: MobileAnalyticsEvent[] = [];
  private isInitialized = false;

  private constructor(config: MobileAnalyticsConfig = {}) {
    this.config = {
      debug: false,
      trackPageViews: true,
      trackEvents: true,
      trackPerformance: true,
      sampleRate: 1.0,
      ...config
    };

    this.sessionId = this.generateSessionId();
  }

  static getInstance(config?: MobileAnalyticsConfig): MobileAnalyticsService {
    if (!MobileAnalyticsService.instance) {
      MobileAnalyticsService.instance = new MobileAnalyticsService(config);
    }
    return MobileAnalyticsService.instance;
  }

  // Initialize analytics
  async initialize(userId?: string): Promise<void> {
    if (this.isInitialized) return;

    this.userId = userId;
    this.isInitialized = true;

    // Track initial page view
    if (this.config.trackPageViews) {
      this.trackPageView();
    }

    // Track performance metrics
    if (this.config.trackPerformance) {
      this.trackPerformance();
    }

    // Setup periodic flush
    this.setupPeriodicFlush();

    // Setup page unload
    this.setupPageUnload();

    if (this.config.debug) {
      console.log('✅ Mobile Analytics initialized', { sessionId: this.sessionId, userId });
    }
  }

  // Track page view
  trackPageView(): void {
    if (!this.shouldTrack()) return;

    const event: MobileAnalyticsEvent = {
      event: 'page_view',
      timestamp: Date.now(),
      sessionId: this.sessionId,
      userId: this.userId,
      deviceInfo: this.getDeviceInfo(),
      page: this.getPageInfo()
    };

    this.trackEvent(event);
  }

  // Track custom event
  track(event: string, properties?: Record<string, any>): void {
    if (!this.shouldTrack()) return;

    const analyticsEvent: MobileAnalyticsEvent = {
      event,
      properties,
      timestamp: Date.now(),
      sessionId: this.sessionId,
      userId: this.userId,
      deviceInfo: this.getDeviceInfo(),
      page: this.getPageInfo()
    };

    this.trackEvent(analyticsEvent);
  }

  // Track user interaction
  trackInteraction(element: string, action: string, properties?: Record<string, any>): void {
    this.track('user_interaction', {
      element,
      action,
      ...properties
    });
  }

  // Track mobile-specific events
  trackMobileGesture(gesture: string, properties?: Record<string, any>): void {
    this.track('mobile_gesture', {
      gesture,
      ...properties
    });
  }

  // Track camera usage
  trackCameraUsage(action: 'capture' | 'upload' | 'view', properties?: Record<string, any>): void {
    this.track('camera_usage', {
      action,
      ...properties
    });
  }

  // Track calendar interactions
  trackCalendarInteraction(action: 'view' | 'create' | 'edit' | 'delete', properties?: Record<string, any>): void {
    this.track('calendar_interaction', {
      action,
      ...properties
    });
  }

  // Track performance metrics
  private trackPerformance(): void {
    if (!window.performance) return;

    const navigation = window.performance.timing;
    const paint = window.performance.getEntriesByType('paint');

    const performanceData = {
      loadTime: navigation.loadEventEnd - navigation.navigationStart,
      domContentLoaded: navigation.domContentLoadedEventEnd - navigation.navigationStart,
      firstContentfulPaint: paint.find(p => p.name === 'first-contentful-paint')?.startTime
    };

    const event: MobileAnalyticsEvent = {
      event: 'performance',
      properties: performanceData,
      timestamp: Date.now(),
      sessionId: this.sessionId,
      userId: this.userId,
      deviceInfo: this.getDeviceInfo(),
      page: this.getPageInfo(),
      performance: performanceData
    };

    this.trackEvent(event);
  }

  // Track error
  trackError(error: Error, context?: Record<string, any>): void {
    this.track('error', {
      message: error.message,
      stack: error.stack,
      context
    });
  }

  // Private methods
  private trackEvent(event: MobileAnalyticsEvent): void {
    this.eventQueue.push(event);

    if (this.config.debug) {
      console.log('📊 Analytics Event:', event);
    }

    // Flush immediately for important events
    if (event.event === 'error' || event.event === 'page_view') {
      this.flush();
    }
  }

  private async flush(): Promise<void> {
    if (this.eventQueue.length === 0) return;

    const events = [...this.eventQueue];
    this.eventQueue = [];

    try {
      // Send to analytics endpoint
      if (this.config.endpoint) {
        await fetch(this.config.endpoint, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'X-API-Key': this.config.apiKey || ''
          },
          body: JSON.stringify({ events })
        });
      }

      if (this.config.debug) {
        console.log('📊 Analytics flushed:', events.length, 'events');
      }
    } catch (error) {
      console.error('❌ Failed to flush analytics:', error);
      // Re-add events to queue for retry
      this.eventQueue.unshift(...events);
    }
  }

  private setupPeriodicFlush(): void {
    setInterval(() => {
      this.flush();
    }, 30000); // Flush every 30 seconds
  }

  private setupPageUnload(): void {
    window.addEventListener('beforeunload', () => {
      this.flush();
    });

    window.addEventListener('pagehide', () => {
      this.flush();
    });
  }

  private shouldTrack(): boolean {
    return Math.random() < (this.config.sampleRate || 1.0);
  }

  private getDeviceInfo() {
    // Create a mock device info object for the service
    return {
      isMobile: false,
      isTablet: false,
      isDesktop: true,
      isIOS: false,
      isAndroid: false,
      screenWidth: 1920,
      screenHeight: 1080,
      orientation: 'landscape' as const
    };
  }

  private getPageInfo() {
    return {
      url: window.location.href,
      title: document.title,
      referrer: document.referrer
    };
  }

  private generateSessionId(): string {
    return Date.now().toString(36) + Math.random().toString(36).substr(2);
  }

  // Get current session info
  getSessionInfo() {
    return {
      sessionId: this.sessionId,
      userId: this.userId,
      eventCount: this.eventQueue.length,
      isInitialized: this.isInitialized
    };
  }
}

// React Hook for using mobile analytics
export const useMobileAnalytics = (config?: MobileAnalyticsConfig) => {
  const serviceRef = useRef(MobileAnalyticsService.getInstance(config));
  const [isInitialized, setIsInitialized] = useState(false);

  useEffect(() => {
    const service = serviceRef.current;

    // Initialize analytics when component mounts
    service.initialize().then(() => {
      setIsInitialized(true);
    });

    // Track page views on route changes
    const handleRouteChange = () => {
      service.trackPageView();
    };

    // Listen for navigation events
    window.addEventListener('popstate', handleRouteChange);
    window.addEventListener('hashchange', handleRouteChange);

    return () => {
      window.removeEventListener('popstate', handleRouteChange);
      window.removeEventListener('hashchange', handleRouteChange);
    };
  }, []);

  const track = (event: string, properties?: Record<string, any>) => {
    serviceRef.current.track(event, properties);
  };

  const trackInteraction = (element: string, action: string, properties?: Record<string, any>) => {
    serviceRef.current.trackInteraction(element, action, properties);
  };

  const trackMobileGesture = (gesture: string, properties?: Record<string, any>) => {
    serviceRef.current.trackMobileGesture(gesture, properties);
  };

  const trackCameraUsage = (action: 'capture' | 'upload' | 'view', properties?: Record<string, any>) => {
    serviceRef.current.trackCameraUsage(action, properties);
  };

  const trackCalendarInteraction = (action: 'view' | 'create' | 'edit' | 'delete', properties?: Record<string, any>) => {
    serviceRef.current.trackCalendarInteraction(action, properties);
  };

  const trackError = (error: Error, context?: Record<string, any>) => {
    serviceRef.current.trackError(error, context);
  };

  return {
    isInitialized,
    track,
    trackInteraction,
    trackMobileGesture,
    trackCameraUsage,
    trackCalendarInteraction,
    trackError,
    getSessionInfo: () => serviceRef.current.getSessionInfo()
  };
};

export default MobileAnalyticsService;

'use client';

import React, { useEffect, useRef, useState } from 'react';

// Extend the global NotificationOptions to include actions and timestamp
declare global {
  interface NotificationOptions {
    actions?: NotificationAction[];
    timestamp?: number;
  }
}

export interface NotificationPermission {
  granted: boolean;
  denied: boolean;
  default: boolean;
}

export interface PushNotification {
  id: string;
  title: string;
  body: string;
  icon?: string;
  badge?: string;
  tag?: string;
  data?: any;
  actions?: NotificationAction[];
  requireInteraction?: boolean;
  silent?: boolean;
  timestamp?: number;
}

export interface NotificationAction {
  action: string;
  title: string;
  icon?: string;
}

class MobileNotificationService {
  private static instance: MobileNotificationService;
  private swRegistration: ServiceWorkerRegistration | null = null;
  private subscription: PushSubscription | null = null;
  private listeners: Set<(notification: PushNotification) => void> = new Set();

  private constructor() {}

  static getInstance(): MobileNotificationService {
    if (!MobileNotificationService.instance) {
      MobileNotificationService.instance = new MobileNotificationService();
    }
    return MobileNotificationService.instance;
  }

  // Initialize the service
  async initialize(): Promise<boolean> {
    try {
      // Register service worker with better error handling
      if ('serviceWorker' in navigator) {
        try {
          // Try to get ready service worker first
          this.swRegistration = await navigator.serviceWorker.ready;
          console.log('✅ Service Worker ready for notifications');
        } catch (error) {
          console.warn('⚠️ Service Worker not ready, trying manual registration:', error);

          // Fallback: try to register manually
          try {
            this.swRegistration = await navigator.serviceWorker.register('/sw.js');
            console.log('✅ Service Worker manually registered');
          } catch (regError) {
            console.warn('⚠️ Manual service worker registration failed:', regError);
            this.swRegistration = null;
          }
        }
      } else {
        console.warn('⚠️ Service Worker not supported in this browser');
        this.swRegistration = null;
      }

      // Get existing subscription
      if (this.swRegistration) {
        try {
          this.subscription = await this.swRegistration.pushManager.getSubscription();
        } catch (subError) {
          console.warn('⚠️ Failed to get push subscription:', subError);
        }
      }

      return true;
    } catch (error) {
      console.error('❌ Failed to initialize push notifications:', error);
      return false;
    }
  }

  // Request notification permission
  async requestPermission(): Promise<NotificationPermission> {
    if (!('Notification' in window)) {
      console.warn('❌ This browser does not support notifications');
      return { granted: false, denied: true, default: false };
    }

    const permission = await Notification.requestPermission();

    return {
      granted: permission === 'granted',
      denied: permission === 'denied',
      default: permission === 'default'
    };
  }

  // Get current permission status
  getPermission(): NotificationPermission {
    if (!('Notification' in window)) {
      return { granted: false, denied: true, default: false };
    }

    const permission = Notification.permission;

    return {
      granted: permission === 'granted',
      denied: permission === 'denied',
      default: permission === 'default'
    };
  }

  // Show local notification (not push)
  async showLocalNotification(notification: PushNotification): Promise<void> {
    const permission = this.getPermission();

    if (!permission.granted) {
      console.warn('❌ Notification permission not granted');
      throw new Error('Notification permission not granted');
    }

    const options: NotificationOptions = {
      body: notification.body,
      icon: notification.icon || '/Logo.svg',
      badge: notification.badge || '/Logo.svg',
      tag: notification.tag,
      data: notification.data,
      requireInteraction: notification.requireInteraction || false,
      silent: notification.silent || false,
      timestamp: notification.timestamp || Date.now()
    };

    if (notification.actions && notification.actions.length > 0) {
      options.actions = notification.actions;
    }

    // Ensure service worker is ready
    if (!this.swRegistration && 'serviceWorker' in navigator) {
      try {
        console.log('🔄 Waiting for service worker registration...');
        this.swRegistration = await navigator.serviceWorker.ready;
        console.log('✅ Service Worker is ready');
      } catch (error) {
        console.warn('⚠️ Service Worker not ready:', error);
      }
    }

    // Try service worker first (works in both mobile and desktop modes)
    if (this.swRegistration) {
      try {
        await this.swRegistration.showNotification(notification.title, options);
        console.log('✅ Notification shown via Service Worker');
        return;
      } catch (error) {
        console.warn('⚠️ Service Worker notification failed, trying Notification API:', error);
      }
    }

    // Try direct Notification API (works in both mobile and desktop modes)
    if ('Notification' in window) {
      try {
        const notificationInstance = new Notification(notification.title, options);

        // Handle notification click
        notificationInstance.onclick = (event) => {
          event.preventDefault();

          // Focus window if it's open
          if (window.focus) {
            window.focus();
          }

          // Handle notification click based on data
          if (notification.data?.url) {
            window.location.href = notification.data.url;
          }

          // Close notification
          notificationInstance.close();
        };

        // Auto-close after 5 seconds if not required interaction
        if (!notification.requireInteraction) {
          setTimeout(() => {
            notificationInstance.close();
          }, 5000);
        }

        console.log('✅ Notification shown via Notification API');
        return;
      } catch (error) {
        console.error('❌ Notification API failed:', error);
      }
    }

    // If all methods fail, show a console notification
    console.warn('⚠️ All notification methods failed, showing console notification');
    console.log('📱 Notification:', notification.title, '-', notification.body);

    // Show a simple alert as last resort
    alert(`${notification.title}\n\n${notification.body}`);

    throw new Error('No notification method available');
  }

  // Check if running on mobile browser
  private isMobileBrowser(): boolean {
    if (typeof window === 'undefined') return false;
    const ua = navigator.userAgent.toLowerCase();
    return /android|webos|iphone|ipad|ipod|blackberry|iemobile|opera mini/i.test(ua);
  }

  // Check if push is supported
  isPushSupported(): boolean {
    return 'serviceWorker' in navigator && 'PushManager' in window;
  }
}

// React Hook for using push notifications
export const useMobileNotifications = () => {
  const [permission, setPermission] = useState<NotificationPermission>({
    granted: false,
    denied: false,
    default: true
  });
  const [isSupported, setIsSupported] = useState(false);
  const serviceRef = useRef(MobileNotificationService.getInstance());

  useEffect(() => {
    const service = serviceRef.current;

    // Check if push is supported
    setIsSupported(service.isPushSupported());

    // Get current permission
    setPermission(service.getPermission());

    // Initialize service
    service.initialize();
  }, []);

  const requestPermission = async (): Promise<NotificationPermission> => {
    const service = serviceRef.current;
    const result = await service.requestPermission();
    setPermission(result);
    return result;
  };

  const showNotification = (notification: PushNotification): void => {
    const service = serviceRef.current;
    service.showLocalNotification(notification);
  };

  return {
    permission,
    isSupported,
    requestPermission,
    showNotification
  };
};

