export interface PatientTypeInfo {
  category: 'menor' | '3ra' | '4ta' | 'adulto';
  label: string;
  colors: {
    header: string;
    badge: string;
    badgeText: string;
  };
}

export function getPatientType(patient: any): PatientTypeInfo {
  // Calculate age from birth date
  const today = new Date();
  const birthDate = new Date(patient.fecha_nacimiento);
  let age = today.getFullYear() - birthDate.getFullYear();
  const monthDiff = today.getMonth() - birthDate.getMonth();

  if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birthDate.getDate())) {
    age--;
  }

  const gender = patient.sexo?.toLowerCase() === 'femenino' ? 'femenino' : 'masculino';

  // Determine patient type based on age
  if (age < 18) {
    // Menores de Edad
    const result: PatientTypeInfo = {
      category: 'menor',
      label: 'Menor',
      colors: gender === 'femenino' ? {
        header: 'from-pink-500 to-pink-700',
        badge: 'bg-pink-100 text-pink-800 dark:bg-pink-900 dark:text-pink-200',
        badgeText: 'border-pink-200 text-pink-700 dark:text-pink-300'
      } : {
        header: 'from-blue-400 to-blue-600',
        badge: 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200',
        badgeText: 'border-blue-200 text-blue-700 dark:text-blue-300'
      }
    }
    return result;
  } else if (age >= 80) {
    // 4ta Edad (80+ years)
    const result: PatientTypeInfo = {
      category: '4ta',
      label: '4ta',
      colors: gender === 'femenino' ? {
        header: 'from-purple-500 to-purple-700',
        badge: 'bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-200',
        badgeText: 'border-purple-200 text-purple-700 dark:text-purple-300'
      } : {
        header: 'from-gray-500 to-gray-700',
        badge: 'bg-gray-100 text-gray-800 dark:bg-gray-900 dark:text-gray-200',
        badgeText: 'border-gray-200 text-gray-700 dark:text-gray-300'
      }
    }
    return result;
  } else if (age >= 60) {
    // 3ra Edad (60-79 years)
    return {
      category: '3ra',
      label: '3ra',
      colors: gender === 'femenino' ? {
        header: 'from-red-400 to-red-600',
        badge: 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200',
        badgeText: 'border-red-200 text-red-700 dark:text-red-300'
      } : {
        header: 'from-yellow-500 to-yellow-700',
        badge: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200',
        badgeText: 'border-yellow-200 text-yellow-700 dark:text-yellow-300'
      }
    };
  } else {
    // Adultos (18-59 years) - Keep original teal colors
    return {
      category: 'adulto',
      label: 'Adulto',
      colors: {
        header: 'from-teal-500 to-cyan-500',
        badge: 'bg-teal-100 text-teal-800 dark:bg-teal-900 dark:text-teal-200',
        badgeText: 'border-teal-200 text-teal-700 dark:text-teal-300'
      }
    };
  }
}

export function calculateAge(fecha_nacimiento: string): number {
  const today = new Date();
  const birthDate = new Date(fecha_nacimiento);
  let age = today.getFullYear() - birthDate.getFullYear();
  const monthDiff = today.getMonth() - birthDate.getMonth();

  if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birthDate.getDate())) {
    age--;
  }

  return age;
}

/**
 * Pregnancy utility functions for calculating pregnancy status and end dates
 */

export interface PregnancyCalculation {
  fechaFin: string;
  semanasRestantes: number;
  estaActivo: boolean;
  semanasTranscurridas: number;
}

/**
 * Calculate pregnancy end date and status based on consultation start date and pregnancy weeks
 * @param fechaInicioConsulta - Date when consultation started (YYYY-MM-DD format)
 * @param semanasEmbarazo - Current pregnancy weeks at consultation time
 * @returns Pregnancy calculation object
 */
export function calculatePregnancyStatus(
  fechaInicioConsulta: string,
  semanasEmbarazo: number
): PregnancyCalculation {
  if (!fechaInicioConsulta || !semanasEmbarazo || semanasEmbarazo <= 0) {
    return {
      fechaFin: '',
      semanasRestantes: 0,
      estaActivo: false,
      semanasTranscurridas: 0
    };
  }

  // Calculate total pregnancy duration (40 weeks is standard full term)
  const totalSemanas = 40;

  // Calculate how many weeks have passed since consultation
  const fechaConsulta = new Date(fechaInicioConsulta);
  const fechaActual = new Date();
  const diasTranscurridos = Math.floor((fechaActual.getTime() - fechaConsulta.getTime()) / (1000 * 60 * 60 * 24));
  const semanasDesdeConsulta = Math.floor(diasTranscurridos / 7);

  // Calculate current pregnancy week
  const semanaActual = semanasEmbarazo + semanasDesdeConsulta;

  // Calculate pregnancy end date (40 weeks from conception)
  // We estimate conception was approximately (semanasEmbarazo) weeks before consultation
  const fechaConcepcionEstimada = new Date(fechaConsulta);
  fechaConcepcionEstimada.setDate(fechaConcepcionEstimada.getDate() - (semanasEmbarazo * 7));

  const fechaFin = new Date(fechaConcepcionEstimada);
  fechaFin.setDate(fechaFin.getDate() + (totalSemanas * 7));

  // Calculate weeks remaining
  const semanasRestantes = Math.max(0, totalSemanas - semanaActual);

  // Pregnancy is active if current week is less than 40 and hasn't ended
  const estaActivo = semanaActual < totalSemanas && fechaActual <= fechaFin;

  return {
    fechaFin: fechaFin.toISOString().split('T')[0], // Format as YYYY-MM-DD
    semanasRestantes,
    estaActivo,
    semanasTranscurridas: semanaActual
  };
}

/**
 * Update pregnancy status when patient data changes
 * @param patientData - Current patient data
 * @returns Updated patient data with calculated pregnancy fields
 */
export function updatePregnancyStatus(patientData: any): any {
  if (patientData.embarazo !== 'si' || !patientData.fecha_inicio || !patientData.semanas_embarazo) {
    return {
      ...patientData,
      embarazo_activo: false,
      embarazo_fecha_fin: null
    };
  }

  const calculation = calculatePregnancyStatus(
    patientData.fecha_inicio,
    patientData.semanas_embarazo
  );

  return {
    ...patientData,
    embarazo_fecha_fin: calculation.fechaFin,
    embarazo_activo: calculation.estaActivo
  };
}

/**
 * Check if patient should still be categorized as pregnant
 * @param patient - Patient object
 * @returns boolean indicating if pregnancy category should apply
 */
export function shouldShowPregnancyCategory(patient: any): boolean {
  return patient.embarazo === 'si' && 
         patient.embarazo_activo === true && 
         patient.sexo === 'femenino';
}

// Record Category Utilities
// Handles historical, active, and archived patient records

export interface RecordCategoryConfig {
  appLaunchDate: Date;
  historicalRecordsEnabled: boolean;
}

export interface HistoricalRecordInfo {
  isHistorical: boolean;
  isArchived: boolean;
  category: 'historical' | 'active' | 'archived';
  archivalDate?: Date;
  transcriptionInfo?: {
    transcribedBy: string;
    transcriptionDate: Date;
    originalDocumentDate?: Date;
  };
}

// Cache configuration to prevent repeated database calls
let cachedConfig: RecordCategoryConfig | null = null;
let configCacheTime: number = 0;
const CONFIG_CACHE_TTL = 60000; // 1 minute cache

// Get app configuration from database or use defaults (with caching)
export const getRecordCategoryConfig = async (): Promise<RecordCategoryConfig> => {
  const now = Date.now();

  // Return cached config if still valid
  if (cachedConfig && (now - configCacheTime) < CONFIG_CACHE_TTL) {
    return cachedConfig;
  }

  try {
    // Import supabase dynamically to avoid server-side issues
    const { supabase } = await import('../lib/supabase');

    // Fetch both configurations in a single query
    const { data, error } = await supabase
      .from('app_configuration')
      .select('config_key, config_value')
      .in('config_key', ['app_launch_date', 'historical_records_enabled']);

    if (error) {
      console.error('Error fetching record category config:', error);
      // Return fallback values on error
      cachedConfig = {
        appLaunchDate: new Date(Date.UTC(2026, 1, 2)), // UTC 2026-02-02
        historicalRecordsEnabled: true
      };
      configCacheTime = now;
      return cachedConfig;
    }

    // Parse configuration values
    const launchDateRecord = data?.find(r => r.config_key === 'app_launch_date');
    const enabledRecord = data?.find(r => r.config_key === 'historical_records_enabled');

    // Use database values or fallback to defaults
    let appLaunchDate: Date;

    if (launchDateRecord?.config_value) {
      // Parse database date (should be 2026-02-02) as UTC
      const [year, month, day] = launchDateRecord.config_value.split('-').map(Number);
      appLaunchDate = new Date(Date.UTC(year, month - 1, day));

      // TEMPORARY FIX: Override database date if it's wrong (2026-02-01 should be 2026-02-02)
      if (launchDateRecord.config_value === '2026-02-01') {
        appLaunchDate = new Date(Date.UTC(2026, 1, 2)); // UTC 2026-02-02
      }
    } else {
      // Fallback to default (matching user requirement: 2026-02-02)
      appLaunchDate = new Date(Date.UTC(2026, 1, 2)); // UTC 2026-02-02
    }

    const historicalRecordsEnabled = enabledRecord?.config_value === 'true';

    // Cache the result
    cachedConfig = {
      appLaunchDate,
      historicalRecordsEnabled
    };
    configCacheTime = now;

    return cachedConfig;
  } catch (error) {
    console.error('Error fetching record category config:', error);
    // Return fallback values on error
    cachedConfig = {
      appLaunchDate: new Date(Date.UTC(2026, 1, 2)), // UTC 2026-02-02 (correct date)
      historicalRecordsEnabled: true
    };
    configCacheTime = now;
    return cachedConfig;
  }
};

// Check if patient record is historical based on fecha_inicio_consulta
export const isHistoricalRecord = (
  fechaInicioConsulta: string | Date,
  config?: RecordCategoryConfig
): boolean => {
  // Handle undefined/null fecha_inicio_consulta
  if (!fechaInicioConsulta) {
    return false;
  }

  // Check if historical records are enabled
  const historicalEnabled = config?.historicalRecordsEnabled ?? true;
  if (!historicalEnabled) {
    return false;
  }

  const launchDate = config?.appLaunchDate || new Date(Date.UTC(2026, 1, 2, 18, 0, 0)); // UTC 2026-02-02 18:00:00 (correct date)

  // Handle different date formats more robustly
  let consultaDate: Date;

  if (typeof fechaInicioConsulta === 'string') {
    // Handle string dates - use UTC to avoid timezone issues
    const dateStr = fechaInicioConsulta.trim();
    // Parse date in UTC to avoid timezone offset issues
    const [year, month, day] = dateStr.split('-').map(Number);
    if (!isNaN(year) && !isNaN(month) && !isNaN(day)) {
      consultaDate = new Date(Date.UTC(year, month - 1, day));
    } else {
      consultaDate = new Date(dateStr);
    }
  } else if (fechaInicioConsulta instanceof Date) {
    // Handle Date objects
    consultaDate = fechaInicioConsulta;
  } else if (typeof fechaInicioConsulta === 'object' && fechaInicioConsulta !== null) {
    // Handle objects that might be Date-like (e.g., from database)
    try {
      consultaDate = new Date(fechaInicioConsulta as any);
    } catch (error) {
      return false;
    }
  } else {
    return false;
  }

  // Check if date is valid
  if (isNaN(consultaDate.getTime())) {
    return false;
  }

  const result = consultaDate < launchDate;

  return result;
};

// Check if patient record should be archived (5 years from last treatment)
export const shouldArchiveRecord = (
  lastTreatmentDate: string | Date
): boolean => {
  const fiveYearsAgo = new Date();
  fiveYearsAgo.setFullYear(fiveYearsAgo.getFullYear() - 5);

  const lastDate = typeof lastTreatmentDate === 'string' 
    ? new Date(lastTreatmentDate) 
    : lastTreatmentDate;

  return lastDate < fiveYearsAgo;
};

// Get complete record category information
export const getRecordCategoryInfo = async (
  fechaInicioConsulta: string | Date,
  lastTreatmentDate?: string | Date
): Promise<HistoricalRecordInfo> => {
  // Handle undefined/null fecha_inicio_consulta
  if (!fechaInicioConsulta) {
    return {
      isHistorical: false,
      isArchived: false,
      category: 'active'
    };
  }

  const config = await getRecordCategoryConfig();

  const isHistorical = isHistoricalRecord(fechaInicioConsulta, config);
  const isArchived = lastTreatmentDate ? shouldArchiveRecord(lastTreatmentDate) : false;

  let category: 'historical' | 'active' | 'archived' = 'active';
  if (isHistorical) {
    category = 'historical';
  } else if (isArchived) {
    category = 'archived';
  }

  const result = {
    isHistorical,
    isArchived,
    category,
    archivalDate: isArchived ? new Date() : undefined
  };

  return result;
};

